
// ══ v676 (Step 0) — BENCHMARK MODE BOOT ═══════════════════════════════════════════════════════════════════════════
// Inert unless the page is opened with the URL hash #tt-benchmark (the panel) or #tt-benchmark-worker (one run, inside
// the panel's iframe). In either mode, BEFORE any other app code runs, browser storage is replaced by an empty in-memory
// store for the whole life of the page (ttBenchInstallSandbox): nothing the page does can read or write the learner's
// saved progress. Only the Gemini key is read (read-only) from real storage, and the learner's vocabulary only when the
// person explicitly asks for a device snapshot. Normal app use (no hash) never reaches any of this.
const TT_BENCH_MODE = (function () {
  try {
    if (typeof window === 'undefined' || typeof location === 'undefined' || !location || window.__TT_HARNESS__) return null
    const h = String(location.hash || '')
    return /^#tt-benchmark-worker(?:$|[&?])/.test(h) ? 'worker' : /^#tt-benchmark(?:$|[&?])/.test(h) ? 'panel' : null
  } catch (e) { return null }
})()
const TT_BENCH_SANDBOX = TT_BENCH_MODE ? ttBenchInstallSandbox() : null

const { useState, useEffect, useCallback, useRef, useMemo } = React

// ── Fonts ────────────────────────────────────────────────────────────────────
const FontStyle = () => (
  <style>{`
    @import url('https://fonts.googleapis.com/css2?family=Sarabun:wght@300;400;500;600;700&family=DM+Mono:ital,wght@0,400;0,500;1,400&family=DM+Serif+Display:ital@0;1&display=swap');
    /* §27 — Japanese must render cleanly alongside Thai; Noto Sans JP falls back
       to platform CJK faces so no glyph boxes appear if the webfont is unavailable. */
    :lang(zh), .zh { font-family: 'Noto Sans SC','PingFang SC','Microsoft YaHei','Heiti SC',sans-serif; }
    :lang(ja), .jp { font-family: 'Noto Sans JP','Hiragino Sans','Yu Gothic UI','Meiryo',sans-serif; }
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { background: #0b1120; }
    :root {
      --bg: #0b1120;
      --surface: #131e35;
      --surface2: #1a2847;
      --gold: #d4a94a;
      --gold-dim: #9a7a35;
      --text: #e8edf5;
      --muted: #6b7c9e;
      --border: #1f3158;
      --new: #4a90e2;
      --learning: #f59e0b;
      --known: #10b981;
      --lapsed: #ef4444;
    }
    .app { font-family: 'Sarabun', sans-serif; background: var(--bg); min-height: 100vh; color: var(--text); }
    .thai { font-family: 'Sarabun', sans-serif; }
    .phon { font-family: 'DM Mono', monospace; }
    .display { font-family: 'DM Serif Display', serif; }
    ::-webkit-scrollbar { width: 4px; }
    ::-webkit-scrollbar-track { background: transparent; }
    ::-webkit-scrollbar-thumb { background: var(--border); border-radius: 2px; }
    .fade-in { animation: fadeIn 0.25s ease; }
    @keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
    .spin { animation: spin 1s linear infinite; }
    @keyframes spin { to { transform: rotate(360deg); } }
    .pulse-dot { animation: pulseDot 1.5s ease-in-out infinite; }
    @keyframes pulseDot { 0%,100%{opacity:.3;transform:scale(.8)} 50%{opacity:1;transform:scale(1)} }
  `}</style>
)

