THAI_LEXICON_AUDIT_V645.forEach(a => {
  const d = RAW_VOCAB.find(x => x && x.id === a.id)
  if (!d || d.t !== a.thai) { a.applied = false; return }
  a.before = { e: d.e, ph: d.ph, note: d.note || null, semanticQc: d.semanticQc, phoneticQc: d.phoneticQc, qcStatus: d.qcStatus, qcIssues: (d.qcIssues || []).slice() }
  Object.assign(d, a.set, { semanticQc: 'PASS', phoneticQc: 'PASS', qcStatus: 'PASS', qcIssues: [], qcAudit: 'v645', verificationEvidence: a.evidence })
  a.applied = true
})


// ══════════════════════════════════════════════════════════════════════════════ — Noob Season One (ThaiPod101 Absolute Beginner S1, Lessons 1-25)
// ── Full-vocab gloss enricher (fills missing gloss dots from all 861 words) ──
const _GLOSS_LOOKUP = (() => {
  const np = s => (s||'').toLowerCase().replace(/[-,.!?]/g,'')
    .replace(/[àáâãāăǎ]/g,'a').replace(/[èéêëēĕě]/g,'e').replace(/[ìíîïīĭǐ]/g,'i')
    .replace(/[òóôõōŏǒ]/g,'o').replace(/[ùúûüūŭǔ]/g,'u')
    .replace(/[əɘ]/g,'a').replace(/ɔ/g,'o').replace(/ɯ/g,'u').replace(/ŋ/g,'ng').replace(/[ʔː]/g,'')
    .trim()
  const m = {}
  const compounds = []   // [{tokens:[normalized], gloss, len}]
  RAW_VOCAB.forEach(v => {
    if (v.dup) return   // suppressed duplicate — its junk data must not shadow the keeper
    const ph = np(v.ph || v.phonetic || '')
    const e = ((v.e || v.english || '').split(/[,/]/)[0]).trim()
    if (!ph || !e) return
    m[ph] = e
    // Build compound lookup for multi-syllable words (hyphen-separated)
    const rawPh = (v.ph || v.phonetic || '')
    const parts = rawPh.split('-')
    if (parts.length >= 2) {
      compounds.push({ tokens: parts.map(p => np(p)), gloss: e, len: parts.length })
    }
  })
  // Sort longest compounds first so we prefer longer matches
  compounds.sort((a, b) => b.len - a.len)
  return { lookup: m, np, compounds }
})()

// Enrich a words array using compound-first matching to avoid wrong single-token glosses
// (e.g. mái in ดอกไม้ should not be glossed as "question particle")
function enrichWordsWithCompounds(words) {
  if (!words || !words.length) return words
  const result = words.map(w => ({ ...w }))
  const { np, lookup, compounds } = _GLOSS_LOOKUP

  // Pre-pass: for single hyphenated tokens (e.g. "thá-ná-tham"), try full normalized lookup
  for (let i = 0; i < result.length; i++) {
    if (!result[i].e && (result[i].p || '').includes('-')) {
      const fullNorm = np(result[i].p)
      if (lookup[fullNorm]) result[i].e = lookup[fullNorm]
    }
  }

  // Pass 1: compound matching — normalize each token and try longest compounds first
  const toks = result.map(w => np(w.p || ''))
  const claimed = new Array(result.length).fill(false)
  for (const comp of compounds) {
    for (let i = 0; i <= toks.length - comp.len; i++) {
      if (claimed[i]) continue
      let match = true
      for (let j = 0; j < comp.len; j++) {
        if (toks[i + j] !== comp.tokens[j]) { match = false; break }
      }
      if (match) {
        if (!result[i].e) result[i].e = comp.gloss
        for (let j = 1; j < comp.len; j++) {
          claimed[i + j] = true
          if (!result[i + j].e) result[i + j].e = ''
        }
        claimed[i] = true
        break
      }
    }
  }

  // Pass 2: unambiguous common-word lookup for claimed=false, e still empty
  // Only apply for normalized phonetics ≥5 chars (short ones are too ambiguous:
  // "mai"=ไม่/ไหม/ใหม่, "kha"=ขา/ค่า, "phak"=ผัก/พัก etc.)
  const COMMON = { phom:'I (male)',chan:'I (female)',khun:'you',rao:'we',ja:'will',
    bpai:'go',maa:'come',mai:'not',dai:'can',mii:'have',dtong:'must',yaak:'want',
    chop:'like',kin:'eat',duu:'look',hen:'see',ruu:'know',kit:'think',
    jaa:'meet',fang:'listen',phoot:'speak',bok:'tell',tham:'do',
    laew:'already',ko:'also',thii:'at',nii:'this',nan:'that',loei:'so/indeed',
    maak:'very',nit:'little',noi:'little',yang:'still',khoei:'ever',
    phoeng:'just now',gamlang:'currently',yuu:'is/stay',pen:'is/be' }
  for (let i = 0; i < result.length; i++) {
    if (!result[i].e) {
      const norm = toks[i]
      // First try common unambiguous words
      if (COMMON[norm]) { result[i].e = COMMON[norm]; continue }
      // Then try vocab lookup — but only for longer normalised phonetics (5+ chars)
      if (norm.length >= 5 && lookup[norm]) result[i].e = lookup[norm]
    }
  }
  return result
}

function enrichGloss(p) { if (!p) return ''; const k = _GLOSS_LOOKUP.np(p); return _GLOSS_LOOKUP.lookup[k] || '' }

// AI fill — sends batches of pairs with empty glosses to the model for completion
async function fillMissingGlossesForTrack(pairs, apiKey, model, onLog) {
  if (!apiKey || !model || !pairs || !pairs.length) return pairs
  const IPA = /[\u025b\u0254\u0250\u0289\u026f\u014b\u0259\u026a\u028a]/
  const DBL = /awaw|oeoe|ueue|aeae/
  // Local pre-fill — covers Thai text AND romanization in p field
  const THAI_GLOSS = {
    'ครับ':'[m]','ค่ะ':'[f]','คะ':'[f]','ไม่':'not','ไหม':'?','มั้ย':'?','ๆ':'(repeat)',
    'จะ':'will','ก็':'also','แล้ว':'already','ที่':'that/at','ให้':'to','นะ':'[softener]',
    'เลย':'so/then','มาก':'very','แค่':'just','ตอน':'at/when','ก่อน':'first/before',
    'กำลัง':'currently','เหรอ':'[surprise?]','เหรอะ':'[surprise?]','เกือบ':'almost',
    'อัน':'[item]','ทำไม':'why','เพราะ':'because','แต่':'but','หรือ':'or',
    'และ':'and','กับ':'with/and','จาก':'from','ถ้า':'if','เมื่อ':'when',
    'ผม':'I (male)','ฉัน':'I (female)','เธอ':'she/you','เขา':'he/she','คุณ':'you',
    'เรา':'we','มัน':'it','ใคร':'who','อะไร':'what','ที่ไหน':'where',
    'นั้น':'that','นี้':'this','นั่น':'that','อยาก':'want','ชอบ':'like',
    'ไป':'go','มา':'come','อยู่':'stay/be','ทำ':'do','พูด':'speak',
    'บอก':'tell','ถาม':'ask','ต้อง':'must','รู้':'know','เห็น':'see',
    'ได้':'can/get','มี':'have','เป็น':'be','ช่วย':'help','ใช้':'use',
    'กิน':'eat','ดื่ม':'drink','นอน':'sleep/lie down','นั่ง':'sit','เดิน':'walk',
    'ว่าย':'swim','ซื้อ':'buy','รับ':'receive','เอา':'take','คิด':'think',
    'เข้าใจ':'understand','จำ':'remember','ลืม':'forget','หา':'look for','เจอ':'find/meet',
    'จริง':'really/true','สวย':'beautiful','ใหญ่':'big','เล็ก':'small','ร้อน':'hot',
    'เย็น':'cool/cold','หนาว':'cold','สนุก':'fun','เหนื่อย':'tired','หิว':'hungry',
    'ดี':'good','เร็ว':'fast','ช้า':'slow','ง่าย':'easy','ยาก':'difficult',
    'บ้าน':'house/home','ห้อง':'room','ทะเล':'sea','หาด':'beach','ทราย':'sand',
    'น้ำ':'water','เกาะ':'island','เมือง':'city','ถนน':'road','ตลาด':'market',
    'สนามบิน':'airport','วัด':'temple','ใกล้':'near','ไกล':'far',
    'ทำ':'do','พื้น':'floor','ช้อน':'spoon','ส้อม':'fork','เรือ':'boat',
    'ตา':'eye','หน้า':'face','มือ':'hand','จมูก':'nose','ผม':'hair',
    'วัน':'day','คืน':'night','เช้า':'morning','เย็น':'evening','ปี':'year',
    'หนึ่ง':'one','สอง':'two','สาม':'three','สี่':'four','ห้า':'five',
    'หก':'six','เจ็ด':'seven','แปด':'eight','เก้า':'nine','สิบ':'ten',
    // Romanized fallbacks
    'khráp':'[m]','kráp':'[m]','krap':'[m]','khrap':'[m]',
    'khâ':'[f]','khà':'[f]','kha':'[f]','ka':'[f]',
    'pai':'go','bpai':'go','maa':'come','yuu':'stay',
    'tîeow':'travel/visit','thîao':'travel/visit',
    'kàw':'island','gàw':'island','kòr':'island',
    'glâi':'near','glai':'near','klai':'near',
    'phǒm':'I (male)','phom':'I (male)',
    'chǎn':'I (female)','chan':'I (female)',
    'thoer':'she/you','thoe':'she/you','ter':'she/you',
    'yàak':'want','yaak':'want',
    'chôop':'like','châwp':'like','chop':'like',
    'nawn':'sleep/lie down','non':'sleep/lie down',
    'bon':'on/above',
    'saai':'sand','sai':'sand/route',
    'jing':'really/true','ching':'really/true',
    'rǒe':'[surprise?]','roe':'[surprise?]',
    'mâi':'not','mai':'not',
    'dii':'good','dee':'good',
    'mii':'have','mi':'have',
    'baan':'house/home','ban':'house/home',
    'hâat':'beach','hat':'beach',
    'nám':'water','nam':'water',
    'gamlang':'currently','gam-lang':'currently',
    'yàak':'want','mâak':'very',
    'pen':'be','bpen':'be',
    'khon':'person','kon':'person',
    'kâo':'rice/enter','khâo':'rice/enter',
    'ao':'take/want','âo':'take/want',
    // More common missing romanized forms
    'chai':'yes/correct','châi':'yes/correct','cha':'yes',
    'man':'it','mán':'it',
    'kamlang':'currently','kam-lang':'currently','gamlang':'currently',
    'nang':'sit','nâng':'sit','nâng':'sit',
    'hin':'stone','hǐn':'stone','hîn':'stone',
    'thi':'that/at','thii':'that/at','thîi':'that/at','thî':'that/at',
    'yen':'cool/cold','yěn':'cool/cold',
    'muean':'like/similar','mǔean':'like/similar','muên':'like/similar',
    'hen':'see','hěn':'see','hên':'see',
    'duay':'also/with','dûay':'also/with','duai':'also/with',
    'ching':'really','jing':'really/true',
    'rao':'we/us','raw':'we/us',
    'khao':'he/she/they','khǎo':'he/she/they',
    'tham':'do/make','tam':'do/make',
    'wai':'put/keep','wây':'put/keep',
    'nam':'water/lead','nám':'water',
    'fan':'dream/tooth','fǎn':'dream',
    'thong':'gold/bag','thǒng':'gold/bag',
    'khwan':'smoke/should','khuan':'should',
    'phra':'holy/monk','phráa':'monk',
    'rok':'disease/fall','rôk':'disease',
    'nit':'little','níd':'little',
    'nit-noi':'a little','nít-nǒoi':'a little',
    'yang':'still/type','yâng':'still/type','yang-ngai':'how',
    'yang-ngân':'still like that',
    'laeo':'already/then','láew':'already',
    'gap':'with/and','gàp':'with',
    'jak':'from','jàak':'from',
    'tang':'set up/from','tâng':'set up',
    'na':'field/face','nâa':'face/next',
    'lang':'after/back','lǎng':'after/back',
    'theung':'arrive/about','thǔeng':'arrive',
    'an':'item/thing','àn':'item',
    'pen':'be','bpen':'be','bpên':'be',
    'yut':'stop','yùt':'stop',
    'run':'generation','rûn':'generation',
    'pen-yang-ngai':'how is it',
    'sabai':'comfortable','sà-baai':'comfortable',
    'aroy':'delicious','à-rǒi':'delicious',
    'noi':'a little','nǒi':'a little',
    'yang':'still','yung':'mosquito',
    'suay':'beautiful','sǔay':'beautiful',
    'jai':'heart/mind','jai-dii':'kind',
    'khit':'think','khîd':'think',
    'ngaan':'work/event','ngaan':'work',
    'rong':'cry/factory','ráwng':'cry',
    'sa-at':'clean','sà-àat':'clean',
    'farang':'foreign/guava','fa-ràng':'foreigner',
    'hua-jai':'heart','hǔa-jai':'heart',
    'tam-mai':'why','tam-mai':'why',
    'yang-ngai':'how','yang-rai':'how',
  }
  const pairs2 = pairs.map(p => {
    if (!p.words) return p
    const ws = p.words.map(w => {
      if (w.e) return w  // already has gloss
      // Check Thai text in p, romanization in p, or romanization in ph
      const gloss = THAI_GLOSS[w.p] || THAI_GLOSS[w.ph] || THAI_GLOSS[(w.ph||'').replace(/[.]/g,'')]
      return gloss ? { ...w, e: gloss } : w
    })
    return ws.some((w, i) => w !== p.words[i]) ? { ...p, words: ws } : p
  })  // double-conversion artifacts from old fixIPAPhonetic
  const HAS_TONE_PH = /[àáâǎèéêěìíîǐòóôǒùúûǔ\u0300\u0301\u0302\u030C]/
  // Clear untoned w.ph AND w.ph that look like particles/pronouns assigned to wrong words
  // (re-romanizer token misalignment creates khráp/phǒm assigned to wrong Thai words)
  const PARTICLES_PH = /^(khr[aá]p|kh[aâ]|ph[oǒ]m|ch[aǎ]n|y[aà]ak|m[aâ]i|n[aá]|lo[eé]i)\.?$/i
  const pairs3 = pairs2.map(p => {
    if (!p.words) return p
    const ws = p.words.map((w, wi) => {
      if (!w.ph || w.ph.length <= 1) return w  // empty/single — already flagged
      if (/[\u0e00-\u0e7f]/.test(w.ph)) return w  // Thai text — keep
      // Mid tone is written WITHOUT a tone mark in this convention, so "no tone marks"
      // does not mean "not a phonetic" (it blanked thai, khun, rao, mii\u2026). Clear only
      // the case this rule was for: the English gloss leaked into the phonetic slot.
      // A value that equals the gloss is only a leak if the pair's own romanised line
      // does not contain it too (\u0E44\u0E17\u0E22 = "Thai" is romanised "thai" as well).
      if (!HAS_TONE_PH.test(w.ph) && w.e && String(w.ph).trim().toLowerCase() === String(w.e).trim().toLowerCase() &&
          !String(p.phonetic || '').toLowerCase().split(/[\s\-]+/).includes(String(w.ph).trim().toLowerCase())) return { ...w, ph: '' }
      // Clear if ph looks like a particle/pronoun but gloss says something different
      // (sign of re-romanizer token misalignment)
      if (PARTICLES_PH.test(w.ph) && w.e && !['[m]','[f]','I (male)','I (female)','not','will','want'].includes(w.e)) {
        return { ...w, ph: '' }
      }
      return w
    })
    return ws.some((w, i) => w !== p.words[i]) ? { ...p, words: ws } : p
  })


  const needsFill = pairs3.map((p, i) => i).filter(i => {
    const ws = pairs3[i].words
    if (!ws) return false
    const thaiLen = (pairs3[i].thai || '').replace(/[^ก-๙]/g, '').length
    const byWords = ws.some(w => !w.e || !w.ph || IPA.test(w.ph || '') || DBL.test(w.ph || ''))
    const byLen = ws.length < 2 && thaiLen > 8
    return byWords || byLen
  })
  if (!needsFill.length) return pairs3

  const result = [...pairs3]
  const BATCH = 5

  for (let b = 0; b < needsFill.length; b += BATCH) {
    const batchIdxs = needsFill.slice(b, b + BATCH)
    const batchNum = Math.floor(b/BATCH)+1
    const totalBatches = Math.ceil(needsFill.length/BATCH)
    const sample = (pairs[batchIdxs[0]]?.thai || '').slice(0,35)
    onLog?.(`  Batch ${batchNum}/${totalBatches}: ${sample}…`)
    // ── Special handling for 1-word pairs with long Thai ─────────────────────
    // splitThaiSyllables produces bad splits (no word boundaries), so for
    // these pairs we do a separate segmentation API call instead
    const oneWordPairs = batchIdxs.filter(pairIdx => {
      const ws = pairs3[pairIdx].words || []
      const thaiLen = (pairs3[pairIdx].thai || '').replace(/[^ก-๙]/g, '').length
      if (thaiLen < 5) return false
      // 1-word pairs
      if (ws.length < 2) return true
      // All-empty-e pairs
      if (ws.every(w => !w.e)) return true
      // Any word has empty e AND romanization in p (not Thai text) — needs segmentation
      // because API can't gloss romanized tokens without Thai context
      const hasRomanizedEmptyE = ws.some(w => !w.e && w.p && !/[\u0e00-\u0e7f]/.test(w.p))
      return hasRomanizedEmptyE
    })
    for (const pairIdx of oneWordPairs) {
      try {
        const p = pairs[pairIdx]
        const thaiLen = (p.thai || '').replace(/[^ก-๙]/g, '').length
        onLog?.(`  🔍 Segmenting 1-word pair [${pairIdx}]: ${(p.thai||'').slice(0,40)}…`)
        const segTokens = Math.min(2500, Math.max(500, Math.round(thaiLen * 15)))
        const segRaw = await geminiGenerate(apiKey, model, [{ role: 'user', content:
          `Segment this Thai sentence into individual words. For each word provide romanization and English.

Thai: ${p.thai}

RULES: ph = toned RTGS only (NO IPA ɔ ə ʉ ŋ — use aw oe ue ng). e = 1-3 word English. Particles: ครับ→"[m]" ค่ะ→"[f]" ไม่→"not" นะ→"[softener]" เลย→"so" มาก→"very" ก็→"also" แล้ว→"already".
CRITICAL: "p" field = the original Thai word/syllable text. "ph" field = toned RTGS romanization.

Return ONLY JSON array, no markdown: [{"p":"ฉัน","e":"I","ph":"chǎn"},{"p":"เห็น","e":"see","ph":"hěn"},...]` }], segTokens)
        const segParsed = JSON.parse(segRaw.replace(/```json|```/g, '').trim())
        if (Array.isArray(segParsed) && segParsed.length >= 2) {
          const cleanedWords = segParsed.map(w => {
            // IPA conversion only. The tone engine used to re-tone every segment here
            // (aa-h\u01CEan \u2192 aa-haan); known words get their canonical phonetic in the
            // final phonetic stage instead.
            const ph = fixIPAPhonetic(w.ph || '')
            return { ...w, ph }
          })
          // Update pair.phonetic to full sentence so re-romanization can add tones
          const fullPh = cleanedWords.map(w => w.ph || w.p || '').filter(x => x && !/[\u0e00-\u0e7f]/.test(x)).join(' ')
          result[pairIdx] = { ...result[pairIdx], words: cleanedWords, phonetic: fullPh || result[pairIdx].phonetic }
          onLog?.(`  ✓ Segmented into ${cleanedWords.length} words`)
        }
      } catch(e) { onLog?.(`  ⚠️ Segmentation failed for pair [${pairIdx}]: ${e.message.slice(0,60)}`) }
    }

    const inputWithIdx = batchIdxs.reduce((acc, pairIdx, localIdx) => {
      const pair = pairs3[pairIdx]
      const ws = pair.words || []
      const thaiLen = (pair.thai || '').replace(/[^ก-๙]/g, '').length
      if (thaiLen < 5) { acc.push({ entry: { id: acc.length, thai: pair.thai || '', words: ws }, origPairIdx: pairIdx }); return acc }
      const allEmpty = ws.every(w => !w.e)
      const hasRomanizedEmptyE = ws.some(w => !w.e && w.p && !/[\u0e00-\u0e7f]/.test(w.p))
      // Skip if handled by segmentation
      if (ws.length < 2 || allEmpty || hasRomanizedEmptyE) return acc
      acc.push({ entry: { id: acc.length, thai: pair.thai || '', words: ws }, origPairIdx: pairIdx })
      return acc
    }, [])
    const input = inputWithIdx.map(x => x.entry)
    const inputPairIdxs = inputWithIdx.map(x => x.origPairIdx)
    // v647: every pair of this batch was already handled by segmentation — the gloss prompt
    // would be sent with "Input: []" and its answer ignored (11 of 15 calls in the audit run).
    if (!input.length) continue

    const prompt = `Fill every empty "e" (English gloss) and "ph" (romanization) in these Thai word arrays.
CRITICAL: Use the "thai" field (the full Thai sentence) to identify each word. The words appear IN ORDER matching the Thai sentence. Even if "p" is romanization, find the corresponding Thai word by position and meaning, then provide its English gloss.
EVERY word with empty "e" MUST get a gloss — no empty strings allowed.
NOTE: The "p" field may contain Thai text OR romanization. Use either to identify the word.



Rules for "e": 1-3 words. PARTICLES: ครับ→"[m]" ค่ะ/คะ→"[f]" ไม่→"not" ไหม/มั้ย→"?" จะ→"will" ก็→"also" แล้ว→"already" ที่→"that/at" ให้→"to" นะ→"[softener]" เลย→"so/then" มาก→"very" แค่→"just" ตอน→"at/when" ก่อน→"first/before" กำลัง→"currently" เหรอ/เหรอะ→"[surprise?]" เกือบ→"almost" อัน→"[item]" ทำไม→"why". NUMBERS: หนึ่ง→"one" สอง→"two" สาม→"three" สี่→"four" ห้า→"five" หก→"six" เจ็ด→"seven" แปด→"eight" เก้า→"nine" สิบ→"ten". Time: โมง→"o'clock" เช้า→"morning" เย็น→"evening" ทุ่ม→"p.m." คืน→"night". CRITICAL HOMOPHONES: หา (hǎa)→"to find" NOT five (five=ห้า=hâa). PROPER NOUNS: if the Thai token is a person's name (romanised capitalised like Nida Somchai), set e="[name]". COMMON WORDS: ห้อง→"room" พื้น→"floor" ช้อน→"spoon" ส้อม→"fork" จาน→"plate" แก้ว→"glass" ถัง→"bucket" ผ้า→"cloth" รีบ→"hurry" ขัด→"scrub" ทำความสะอาด→"clean" นั่งเล่น→"living room" ห้องนั่งเล่น→"living room" เสร็จ→"finished/done" ต้อง→"must" รู้→"know" หา→"look for" เจอ→"find/meet" นาน→"long time" สบาย→"well/comfortable".

Rules for "ph": toned RTGS only — NO IPA (no ɛ ɔ ʉ ŋ ə). Use standard Latin with tone marks only (à á â ǎ). Examples: ครับ→"khráp" ค่ะ→"khâ" ไม่→"mâi" สวัสดี→"sà-wàt-dii" อยาก→"yàak" มาก→"mâak". If a word already has a "ph" value but it contains IPA characters (like ɛ ə ʉ ŋ ɔ), REPLACE it with correct toned RTGS.

Keep existing non-empty "e" values exactly as-is. For "ph": keep existing values ONLY if they contain no IPA characters — if "ph" has ɛ ə ʉ ŋ ɔ ɪ ʊ, replace it with correct toned RTGS.

Input: ${JSON.stringify(input)}

Return ONLY valid JSON array: [{"id":0,"words":[{"p":"...","e":"...","ph":"..."},...]},...]`

    try {
      const raw = await geminiGenerate(apiKey, model, [{ role: 'user', content: prompt }], 1200)
      const parsed = JSON.parse(raw.replace(/```json|```/g, '').trim())
      if (Array.isArray(parsed)) {
        for (const item of parsed) {
          const origPairIdx = inputPairIdxs[item.id]
          if (origPairIdx !== undefined && Array.isArray(item.words) && item.words.length > 0) {
            const origWords = pairs[origPairIdx]?.words || []
            const HAS_TONE = /[àáâǎèéêěìíîǐòóôǒùúûǔÀÁÂǍÈÉÊĚÌÍÎǏÒÓÔǑÙÚÛǓ\u0300\u0301\u0302\u030C]/
            const cleanedWords = item.words.map((w, wi) => {
              const origPh = origWords[wi]?.ph || ''
              let ph = w.ph ? fixIPAPhonetic(w.ph) : w.ph
              // Don't overwrite a correctly-toned ph with an untoned one from the API
              if (origPh && HAS_TONE.test(origPh) && (!ph || !HAS_TONE.test(ph))) ph = origPh
              return { ...w, ph }
            })
            result[origPairIdx] = { ...result[origPairIdx], words: cleanedWords }
          }
        }
      }
    } catch(e) { console.warn('[fillGlosses] batch', b, 'failed:', e.message) }
  }
  // ── Vocab phonetic correction pass ──────────────────────────────────────────
  // Fix two generation errors:
  // 1. Wrong tone marks on known words (e.g. AI writes "krung-thèep" instead of "grung-thêep")
  // 2. English words appearing as phonetic tokens (e.g. "family" instead of "khrôop-khrua")
  ;(() => {
    const thaiToPhon = {}
    const engToPhon = {}
    const normKey = s => (s||'').toLowerCase().replace(/[-]/g,' ').trim()
    RAW_VOCAB.forEach(v => {
      if (v.dup) return   // suppressed duplicate — would otherwise overwrite the keeper's phonetic
      const ph = v.ph || v.phonetic || ''
      if (!ph) return
      if (v.t && !thaiToPhon[v.t]) thaiToPhon[v.t] = ph   // first (lowest-id) entry wins
      const eng = normKey(v.e || v.english || '')
      if (eng && !engToPhon[eng]) engToPhon[eng] = ph
    })
    // Hard-coded proper-name overrides (phonetic variants AI commonly hallucinates)
    const PHON_OVERRIDES = {
      'krung-theep': 'grung-thêep', 'krung theep': 'grung-thêep',
      'krung-thèep': 'grung-thêep', 'krung-thêep': 'grung-thêep',
      'kuman thong': 'ku-maan-thoong', 'kuman': 'ku-maan-thoong',
      'bangkok': 'grung-thêep',
    }
    const IS_LATIN_NO_TONE = s => /^[a-zA-Z][a-zA-Z\s\-]*$/.test(s) && !/[àáâǎèéêěìíîǐòóôǒùúûǔ]/.test(s)
    for (let i = 0; i < result.length; i++) {
      const p = result[i]
      if (!p || !p.words || !p.words.length) continue
      let changed = false
      const fixedWords = p.words.map(w => {
        const tok = w.p || ''
        // Case 1: Thai token — override ph if vocab has a known phonetic
        if (/[\u0e00-\u0e7f]/.test(tok) && thaiToPhon[tok]) {
          const correct = thaiToPhon[tok]
          if ((w.ph || '') !== correct) { changed = true; return { ...w, ph: correct } }
          return w
        }
        // Case 2: Latin token without tone marks = English gloss leaked into phonetic slot
        if (IS_LATIN_NO_TONE(tok)) {
          const key = normKey(tok)
          const fix = PHON_OVERRIDES[key] || engToPhon[key]
          if (fix) { changed = true; return { ...w, p: fix, ph: fix, e: w.e || tok } }
        }
        // Case 3: ph/p field contains a known-wrong phonetic for a proper noun
        const phField = normKey(w.ph || w.p || '')
        if (PHON_OVERRIDES[phField]) {
          changed = true
          return { ...w, ph: PHON_OVERRIDES[phField] }
        }
        return w
      })
      if (changed) {
        const newPh = fixedWords
          .map(w => w.ph || w.p || '')
          .filter(x => x && !/[\u0e00-\u0e7f]/.test(x))
          .join(' ')
        result[i] = { ...p, words: fixedWords, phonetic: newPh || p.phonetic }
      }
    }
  })()

  return result
}


