// ── SRS Logic ────────────────────────────────────────────────────────────────
const APP_VERSION = (() => { try { return document.querySelector('meta[name="app-version"]')?.content || 'v131' } catch { return 'v131' } })()

const EASE = { easy: 2.5, ok: 1.3, hard: 0.6 }
function calcInterval(cur, rating) {
  // A failed recall must actually shorten the interval. The old formula multiplied
  // by 0.6*1.5 = 0.9, so a 60-day word came back in 54 days — no real penalty.
  // Cut to 30% (floor 1 day), matching Anki's relearning behaviour.
  if (rating === 'hard') return Math.max(1, Math.round(Math.max(cur, 1) * 0.3))
  return Math.min(Math.round(Math.max(cur, 1) * (EASE[rating] || 1.3) * 1.5), 365)
}
// Consecutive non-fail reviews required to auto-promote a word to 'known'.
// 7 puts the interval at ~117 days (~8 months of consistent correct recall),
// well past Anki's 21-day maturity threshold. Lapsed words must re-earn it with 9.
// A word is only fit to be a generation target if its data is intact. Some lesson-scraped
// entries have no English gloss or residual U+FFFD corruption; those must never be chosen
// as target vocabulary even though they remain in the deck.
function isUsableWord(w) {
  if (!w || !w.thai) return false
  if (w.duplicateOf) return false   // suppressed duplicate; the keeper entry holds the history
  if (/\uFFFD/.test(w.thai)) return false
  const e = (w.english || '').trim()
  if (!e || /\uFFFD/.test(e)) return false
  return true
}
// \u00A724 \u2014 voice configuration per language. Thai keeps its existing WaveNet/Chirp voices
// untouched; Japanese gets ja-JP voices. Nothing Thai-specific is hardcoded into the
// Japanese path and no Japanese text is ever sent to a Thai voice.
const TTS_VOICES = {
  th: { languageCode:'th-TH', male:'th-TH-Chirp3-HD-Charon', female:'th-TH-Chirp3-HD-Aoede' },
  ja: { languageCode:'ja-JP', male:'ja-JP-Neural2-C',        female:'ja-JP-Neural2-B' },
  zh: { languageCode:'zh-CN', male:'cmn-CN-Wavenet-C',       female:'cmn-CN-Wavenet-A' },
}
function ttsVoiceFor(langCode, isMale) {
  const v = TTS_VOICES[langCode] || TTS_VOICES.th
  return { languageCode: v.languageCode, name: isMale ? v.male : v.female }
}
function pickBrowserVoice(langCode) {
  try {
    const want = (TTS_VOICES[langCode] || TTS_VOICES.th).languageCode
    const vs = window.speechSynthesis ? window.speechSynthesis.getVoices() : []
    return vs.find(v => v.lang === want) || vs.find(v => v.lang && v.lang.startsWith(want.slice(0,2))) || null
  } catch { return null }
}



