  const pat = ZH_TARGET_PATTERNS[zh]
  const ex = []
  try { for (let r = 1; r <= 3 && ex.length < 2; r++) { const fb = mandarinFallbackPair(target, inv, r, null, vocab, rules); if (fb && fb.chinese && !ex.includes(fb.chinese)) ex.push(fb.chinese) } } catch (e) {}
