const JA_SPEECH_STYLE_ALIASES = Object.freeze({ polite: 'polite', 'です・ます': 'polite', desu_masu: 'polite', formal: 'polite',
  natural: 'natural', friendly: 'natural', 'friendly everyday japanese': 'natural', default: 'natural', normal: 'natural', everyday: 'natural',
  casual: 'casual', very_casual: 'casual', 'very casual': 'casual', 'very-casual': 'casual', slang: 'casual', 'slang & close-friend speech': 'casual' })
function canonicalJapaneseSpeechStyle(x) { return JA_SPEECH_STYLE_ALIASES[String(x == null ? '' : x).trim().toLowerCase()] || JA_REGISTER_DEFAULT }
function japaneseSpeechStyleName(id) { return { polite: 'polite', natural: 'natural', casual: 'very_casual' }[canonicalJapaneseSpeechStyle(id)] }

// ══ v667 — DETERMINISTIC JAPANESE REGISTER ANALYSER ═══════════════════════════════════════════
// Each sentence of a line is classified by its FINAL predicate (morphology, not one suffix): polite (です/ます family,
// ください, でしょう, ましょう), plain (plain verb / adjective / だ, て-requests, sentence-final よ/ね/の/かな/じゃん …),
// very casual (じゃん, マジ, めっちゃ, やばい, contractions), or neutral (greetings / thanks / bare nouns / はい・うん alone).
const JA_FIXED_NEUTRAL = /^(こんにちは|こんばんは|おはよう|さようなら|いただきます|ごちそうさま(でした)?|おやすみ(なさい)?|はじめまして|はい|いいえ|うん|ううん|ええ|へえ|あ|ああ|えっ?|そう|ほんと|本当|お疲れ様(です)?|ありがとう(ございます)?|すみません|ごめん(なさい)?|どうも|よろしく(お願いします)?)$/
const JA_POLITE_END = /(です|ます|ません|ました|でした|ましょう|ませんか|ましょうか|ください|でしょう|でしょうか|ございます)(か|ね|よ|よね|けど|が)?$/
const JA_VERY_CASUAL = /(じゃん|っしょ|マジ|めっちゃ|やばい|ヤバい|ってか|てか|すげ|ウケる|だろ|かよ|んだよ|ちゃう|てる|てん|すんの|てんの|じゃね)/
const JA_PLAIN_END = /(だ|だよ|だね|だよね|だな|だっけ|じゃない|じゃん|よ|ね|よね|の|のね|かな|かも|けど|って|な|さ|わ|ぞ|ぜ|ん|る|う|く|す|つ|ぬ|ぶ|む|ぐ|た|だった|い|ない|なかった|て|で|ろ|か|っけ|かい)$/
// `exempt`: lesson-word surfaces (e.g. すみません, ください) — a sentence whose politeness IS the lesson word is neutral
function analyseJapaneseRegister(line, exempt) {
  const text = String((line && (line.japanese || line.text)) || line || '').trim()
  const sentences = text.split(/[。！？!?\n]+/).map(x => x.replace(/[、，,\s「」『』（）()…〜~ー]+$/g, '').replace(/^[、，,\s「」]+/, '').trim()).filter(Boolean)
  const sig = { politeMarkers: 0, plainMarkers: 0, casualMarkers: 0, veryCasualMarkers: 0, fixedExpressionExceptions: 0, sentences: [] }
  sentences.forEach(s => {
    const core = s.replace(/^(うん|ううん|ええ|はい|いや|あ|ああ|えっと|そう|じゃあ|でも)[、,\s]*/, '')
    let kind = 'neutral'
    const ex = (exempt || []).find(w => w && JA_POLITE_END.test(w) && new RegExp(w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(か|ね|よ|よね|けど|が)?$').test(core))
    if (JA_FIXED_NEUTRAL.test(s) || JA_FIXED_NEUTRAL.test(core) || !core || ex) { kind = 'neutral'; sig.fixedExpressionExceptions++ }
    else if (JA_POLITE_END.test(core)) { kind = 'polite'; sig.politeMarkers++ }
    else if (JA_VERY_CASUAL.test(core)) { kind = 'very_casual'; sig.veryCasualMarkers++; sig.plainMarkers++ }
    else if (/[぀-ゟ]$/.test(core) && JA_PLAIN_END.test(core)) { kind = 'plain'; sig.plainMarkers++; if (/(よ|ね|よね|の|かな|じゃん|って|な|さ)$/.test(core)) sig.casualMarkers++ }
    else if (/[一-鿿゠-ヿ]$/.test(core) && s.length <= 6) { kind = 'neutral'; sig.fixedExpressionExceptions++ }   // a bare noun ("ここ", "駅")
    else if (/[一-鿿゠-ヿ]$/.test(core)) { kind = 'plain'; sig.plainMarkers++ }                                     // noun-ending statement without だ/です (casual ellipsis)
    sig.sentences.push({ text: s, kind })
  })
  const register = sig.politeMarkers && (sig.plainMarkers) ? 'mixed' : sig.politeMarkers ? 'polite' : sig.plainMarkers ? (sig.veryCasualMarkers ? 'very_casual' : 'plain') : 'neutral'
  return { ...sig, register }
}
// what a scene is expected to sound like: track speech style × the scene's relationship
const JA_SERVICE_RELATIONSHIP = /customer|shop staff|staff|clerk|waiter|stranger|service|reception|teacher|boss/i
function japaneseRegisterExpectation(style, relationship) {
  const st = canonicalJapaneseSpeechStyle(style), service = JA_SERVICE_RELATIONSHIP.test(String(relationship || ''))
  if (st === 'polite') return { style: st, expected: 'polite', label: 'polite です/ます Japanese', offRegister: 'plain', limit: 0.25 }
  if (service) return { style: st, expected: 'service', label: 'contextually polite service interaction', offRegister: null, limit: 1 }
  if (st === 'casual') return { style: st, expected: 'plain', label: 'close-friend casual Japanese', offRegister: 'polite', limit: 0.15 }
  return { style: st, expected: 'plain', label: 'plain / friendly everyday Japanese', offRegister: 'polite', limit: (JAPANESE_REGISTER_RULES.natural && JAPANESE_REGISTER_RULES.natural.politeLimit) || 0.25 }
}
// one scene: {verdict, politeLines, plainLines, offLines[], mismatch(whole scene), reason}
function japaneseSceneRegisterAudit(lines, style, relationship, exempt) {
  const ex = japaneseRegisterExpectation(style, relationship)
  const rows = (lines || []).map((t, k) => ({ k, a: analyseJapaneseRegister(t, exempt) }))
  const isPolite = r => r.a.register === 'polite' || (r.a.register === 'mixed' && r.a.politeMarkers >= r.a.plainMarkers)
  const isPlain = r => r.a.register === 'plain' || r.a.register === 'very_casual' || (r.a.register === 'mixed' && r.a.plainMarkers > r.a.politeMarkers)
  const politeLines = rows.filter(isPolite).length, plainLines = rows.filter(isPlain).length, classified = politeLines + plainLines
  if (!ex.offRegister) return { ...ex, relationship: relationship || '', politeLines, plainLines, offLines: [], verdict: 'PASS', mismatch: false, reason: 'service context: politeness is appropriate' }
  const off = rows.filter(ex.offRegister === 'polite' ? isPolite : isPlain)
  const allowed = Math.max(ex.expected === 'polite' ? 1 : (ex.style === 'casual' ? 0 : 1), Math.floor(ex.limit * classified))
  const fail = off.length > allowed
  const mismatch = fail && classified > 0 && off.length / classified >= 0.5
  const what = ex.offRegister === 'polite' ? 'sustained です/ます' : 'plain/casual drift'
  return { ...ex, relationship: relationship || '', politeLines, plainLines, offLines: off.map(r => r.k), verdict: fail ? 'FAIL' : 'PASS', mismatch,
    reason: fail ? what + ' (' + off.length + '/' + classified + ' lines) despite ' + (relationship || 'the relationship') + ' in ' + japaneseSpeechStyleName(ex.style) + ' mode' : 'consistent ' + ex.label }
}
const POLITE_RX = /(\u3067\u3059|\u307E\u3059|\u3067\u3057\u305F|\u307E\u3057\u305F|\u3067\u3059\u304B|\u307E\u3059\u304B)(\u304B|\u306D|\u3088)?[\u3002\uFF1F\uFF01]?$/

// ── Japanese morphology ──────────────────────────────────────────────────────
// Real conjugation tables, not guesswork. §5 is explicit that a る ending does not
// imply ichidan (帰る/入る/知る/乗る/取る/作る are godan), and that 行く, する, 来る and いい
// need special handling. Forms produced here feed the target matcher so that an
// inflected appearance counts without weakening the matcher into false positives.
const JA_GODAN_TE = {
  'く':['いて','いた'], 'ぐ':['いで','いだ'], 'す':['して','した'],
  'つ':['って','った'], 'る':['って','った'], 'う':['って','った'],
  'ぬ':['んで','んだ'], 'ぶ':['んで','んだ'], 'む':['んで','んだ'],
}
const JA_GODAN_A = { 'く':'か','ぐ':'が','す':'さ','つ':'た','る':'ら','う':'わ','ぬ':'な','ぶ':'ば','む':'ま' }
const JA_GODAN_I = { 'く':'き','ぐ':'ぎ','す':'し','つ':'ち','る':'り','う':'い','ぬ':'に','ぶ':'び','む':'み' }
const JA_GODAN_E = { 'く':'け','ぐ':'げ','す':'せ','つ':'て','る':'れ','う':'え','ぬ':'ね','ぶ':'べ','む':'め' }
const JA_GODAN_O = { 'く':'こ','ぐ':'ご','す':'そ','つ':'と','る':'ろ','う':'お','ぬ':'の','ぶ':'ぼ','む':'も' }

function japaneseConjugate(lemma, cls) {
  const L = lemma || ''
  if (!L) return []
  const out = new Set([L])
  const add = (...xs) => xs.forEach(x => x && out.add(x))
  const stem = L.slice(0, -1)
  const end  = L.slice(-1)

  if (cls === 'ichidan') {
    add(stem+'た', stem+'て', stem+'ない', stem+'なかった', stem+'ます', stem+'ました',
        stem+'ません', stem+'たい', stem+'よう', stem+'れば', stem+'られる', stem)
  } else if (cls === 'godan' || cls === 'godan-iku') {
    // 行く is the classic exception: 行いて is wrong, it is 行って
    const te = (cls === 'godan-iku') ? ['って','った'] : (JA_GODAN_TE[end] || ['って','った'])
    add(stem+te[0], stem+te[1])
    add(stem+JA_GODAN_A[end]+'ない', stem+JA_GODAN_A[end]+'なかった')
    add(stem+JA_GODAN_I[end], stem+JA_GODAN_I[end]+'ます', stem+JA_GODAN_I[end]+'ました',
        stem+JA_GODAN_I[end]+'ません', stem+JA_GODAN_I[end]+'たい')
    add(stem+JA_GODAN_E[end], stem+JA_GODAN_E[end]+'ば', stem+JA_GODAN_E[end]+'る')
    add(stem+JA_GODAN_O[end]+'う')
    // v671 §B3 — colloquial forms: short volitional (行こっか), ちゃう / じゃう (行っちゃう, 飲んじゃう)
    if (/[\u4E00-\u9FFF]/.test(stem)) add(stem+JA_GODAN_O[end], stem+te[0].replace(/て$/, 'ちゃ').replace(/で$/, 'じゃ'))
  } else if (cls === 'irregular-suru') {
    add('した','して','しない','しなかった','します','しました','しません','したい','しよう','できる','し')
    add('しよ','しちゃ','しましょう','しとく','してる')                       // v671 colloquial
  } else if (cls === 'irregular-kuru') {
    add('来た','来て','来ない','来なかった','来ます','来ました','来ません','来たい','来よう','来れば','来')
    // v671 §B3 — 来る written in kana (きた / こない / きます …); only forms of 3+ kana, which cannot hide inside other words
    add('こない','こなかった','きます','きました','きません','きたい','こよう','くれば','きてる','きちゃ')
  } else if (cls === 'irregular-aru') {
    add('あった','あって','ない','なかった','あります','ありました','ありません','あれば')
  } else if (cls === 'i-adjective') {
    add(stem+'かった', stem+'くない', stem+'くなかった', stem+'くて', stem+'く', stem+'ければ', stem+'すぎる', stem+'そう')
  } else if (cls === 'irregular-ii') {
    // いい inflects from よい: よかった / よくない / よくて
    add('よかった','よくない','よくなかった','よくて','よく','よければ','いいです','よい')
  } else if (cls === 'na-adjective' || cls === 'noun') {
    add(L+'だ', L+'です', L+'だった', L+'でした', L+'じゃない', L+'ではない',
        L+'じゃなかった', L+'で', L+'な')
  }
  return [...out]
}

// ── Japanese romaji: deterministic kana → Hepburn ────────────────────────────
// §6 — romaji must not depend on an LLM when the kana reading already determines it.
// This also gives Japanese QC a ground truth to repair against, instead of the Thai
// RTGS re-romanizer which produced sà-wàt-dii for こんにちは.
const KANA_ROMAJI = {
  'きゃ':'kya','きゅ':'kyu','きょ':'kyo','しゃ':'sha','しゅ':'shu','しょ':'sho',
  'ちゃ':'cha','ちゅ':'chu','ちょ':'cho','にゃ':'nya','にゅ':'nyu','にょ':'nyo',
  'ひゃ':'hya','ひゅ':'hyu','ひょ':'hyo','みゃ':'mya','みゅ':'myu','みょ':'myo',
  'りゃ':'rya','りゅ':'ryu','りょ':'ryo','ぎゃ':'gya','ぎゅ':'gyu','ぎょ':'gyo',
  'じゃ':'ja','じゅ':'ju','じょ':'jo','びゃ':'bya','びゅ':'byu','びょ':'byo',
  'ぴゃ':'pya','ぴゅ':'pyu','ぴょ':'pyo',
  'あ':'a','い':'i','う':'u','え':'e','お':'o',
  'か':'ka','き':'ki','く':'ku','け':'ke','こ':'ko',
  'が':'ga','ぎ':'gi','ぐ':'gu','げ':'ge','ご':'go',
  'さ':'sa','し':'shi','す':'su','せ':'se','そ':'so',
  'ざ':'za','じ':'ji','ず':'zu','ぜ':'ze','ぞ':'zo',
  'た':'ta','ち':'chi','つ':'tsu','て':'te','と':'to',
  'だ':'da','ぢ':'ji','づ':'zu','で':'de','ど':'do',
  'な':'na','に':'ni','ぬ':'nu','ね':'ne','の':'no',
  'は':'ha','ひ':'hi','ふ':'fu','へ':'he','ほ':'ho',
  'ば':'ba','び':'bi','ぶ':'bu','べ':'be','ぼ':'bo',
  'ぱ':'pa','ぴ':'pi','ぷ':'pu','ぺ':'pe','ぽ':'po',
  'ま':'ma','み':'mi','む':'mu','め':'me','も':'mo',
  'や':'ya','ゆ':'yu','よ':'yo',
  'ら':'ra','り':'ri','る':'ru','れ':'re','ろ':'ro',
  'わ':'wa','を':'wo','ん':'n',
  'ぁ':'a','ぃ':'i','ぅ':'u','ぇ':'e','ぉ':'o','ゃ':'ya','ゅ':'yu','ょ':'yo',
}
function kataToHira(s) {
  return (s || '').replace(/[\u30A1-\u30F6]/g, ch => String.fromCharCode(ch.charCodeAt(0) - 0x60))
}
// Converts a kana reading to Hepburn romaji. Handles っ (gemination), ん before
// vowels/y (n'), long vowels and katakana ー.
function kanaToRomaji(reading) {
  let s = kataToHira(reading || '')
  s = s.replace(/[\u3000\s]/g, ' ')
  let out = ''
  let i = 0
  while (i < s.length) {
    const two = s.slice(i, i + 2)
    const one = s[i]
    if (one === 'っ') {                                  // gemination: double next consonant
      const nx = KANA_ROMAJI[s.slice(i + 1, i + 3)] || KANA_ROMAJI[s[i + 1]] || ''
      // っ before ch doubles the c (どっち = docchi), matching the dictionary. Mapping
      // it to 't' gave "dotchi", the only romaji disagreement in the whole bank — and
      // it made どっち unbuildable: "segment romaji mismatch" killed every recall.
      if (nx) out += nx[0]
      i += 1; continue
    }
    if (one === 'ー') {                                   // long mark: repeat last vowel
      const last = out.slice(-1)
      if (/[aiueo]/.test(last)) out += last
      i += 1; continue
    }
    if (two.length === 2 && KANA_ROMAJI[two]) { out += KANA_ROMAJI[two]; i += 2; continue }
    // Particle は is read "wa" and へ is read "e". Treat them as particles when they
    // stand between words or end a clause — this is what makes こんにちは -> konnichiwa.
    if (one === 'は' || one === 'へ') {
      const prev = s[i - 1], next = s[i + 1]
      const boundary = !next || /[、。？！\s]/.test(next)
      const isParticle = boundary || (prev && !/[ぁ-ゟ]/.test(prev)) ||
                         (s.slice(0, i + 1) === 'こんにちは') || (s.slice(0, i + 1) === 'こんばんは')
      if (isParticle) { out += (one === 'は' ? 'wa' : 'e'); i += 1; continue }
    }
    if (KANA_ROMAJI[one]) {
      let r = KANA_ROMAJI[one]
      if (one === 'ん') {
        const nxt = s[i + 1]
        const nr = KANA_ROMAJI[s.slice(i + 1, i + 3)] || KANA_ROMAJI[nxt] || ''
        if (nr && /^[aiueoy]/.test(nr)) r = "n'"          // ん before vowel/y
      }
      out += r; i += 1; continue
    }
    if (/[\u3001\u3002\uFF1F\uFF01]/.test(one)) { out += (one === '\u3001' ? ', ' : (one === '\u3002' ? '. ' : one)); i += 1; continue }
    out += one; i += 1
  }
  return out.replace(/\s+/g, ' ').replace(/\s+([.,])/g, '$1').trim()
}
// Comparison ignores spacing/apostrophes/punctuation: word-splitting is a style choice.
function romajiKey(r) { return (r || '').toLowerCase().replace(/[^a-z]/g, '') }
function romajiMatchesReading(romaji, reading) {
  if (!reading) return true
  const a = romajiKey(romaji), b = romajiKey(kanaToRomaji(reading))
  if (a === b) return true
  // v671 §B3 — the particles は / へ / を are romanised by pronunciation (wa / e / o) while the kana spells ha / he / wo:
  // the same normalisation on both sides (あれはなに ↔ are wa nani)
  const loose = x => x.replace(/wa/g, 'ha').replace(/wo/g, 'o').replace(/he/g, 'e')
  return loose(a) === loose(b)
}

// ── Japanese content-vocabulary control ──────────────────────────────────────
// Productive recall only works if the learner can actually form the answer. The
// generator must therefore be restricted to a CLOSED lexical set: current targets
// plus everything genuinely introduced before, plus a controlled grammar scaffold.
// Prompting alone proved insufficient (Gemini produced 映画/雨/予定 on track one),
// so this is enforced by the validator, not just requested.

// §5 — grammar scaffold. These are structural, never SRS vocabulary: they take no
// slot, earn no Known status and do not affect rank. They unlock by rank so the
// whole grammar system is not opened at Mukyu.
const JAPANESE_GRAMMAR_SCAFFOLD = [
  { id:'wa',   form:'\u306F',   romaji:'wa',   meaning:'topic marker',        type:'particle', minKnown:0, minIntroduced:0 },
  { id:'ka',   form:'\u304B',   romaji:'ka',   meaning:'question marker',     type:'particle', minKnown:0, minIntroduced:0 },
  { id:'ne',   form:'\u306D',   romaji:'ne',   meaning:'right? / soft agreement', type:'particle', minKnown:0, minIntroduced:0 },
  { id:'yo',   form:'\u3088',   romaji:'yo',   meaning:'emphasis',            type:'particle', minKnown:0, minIntroduced:0 },
  { id:'da',   form:'\u3060',   romaji:'da',   meaning:'plain copula (is)',   type:'copula',   minKnown:0, minIntroduced:0 },
  { id:'ni',   form:'\u306B',   romaji:'ni',   meaning:'to / at (destination or time)', type:'particle', minKnown:0, minIntroduced:0 },
  { id:'no',   form:'\u306E',   romaji:'no',   meaning:'possessive / explanatory', type:'particle', minKnown:100, minIntroduced:20 },
  { id:'wo',   form:'\u3092',   romaji:'wo',   meaning:'object marker',       type:'particle', minKnown:100, minIntroduced:15 },
  { id:'mo',   form:'\u3082',   romaji:'mo',   meaning:'also / too',          type:'particle', minKnown:100, minIntroduced:30 },
  { id:'to',   form:'\u3068',   romaji:'to',   meaning:'and / with',          type:'particle', minKnown:200, minIntroduced:25 },
  { id:'de',   form:'\u3067',   romaji:'de',   meaning:'at / by means of',    type:'particle', minKnown:200, minIntroduced:35 },
  { id:'ga',   form:'\u304C',   romaji:'ga',   meaning:'subject marker',      type:'particle', minKnown:200, minIntroduced:45 },
  { id:'kara', form:'\u304B\u3089', romaji:'kara', meaning:'from / because',  type:'particle', minKnown:350, minIntroduced:55 },
  { id:'made', form:'\u307E\u3067', romaji:'made', meaning:'until',           type:'particle', minKnown:350, minIntroduced:70 },
  { id:'he',   form:'\u3078',   romaji:'e',    meaning:'towards',             type:'particle', minKnown:350, minIntroduced:80 },
]
// ── Morphology as declarable grammar ────────────────────────────────────────
// JA_MORPHOLOGY_MARKERS blocks たい/ない/ます/ている/たら/けど when undeclared, but
// nothing could ever declare them: the scaffold held particles only. These entries
// give each form an unlock point so natural Japanese becomes buildable.
const JAPANESE_MORPHOLOGY_SCAFFOLD = [
  { form:'\u307E\u3059', id:'masu',  meaning:'polite verb ending',        minKnown:0,  minIntroduced:25 },
  { form:'\u306A\u3044', id:'nai',   meaning:'plain negative',            minKnown:0,  minIntroduced:35 },
  { form:'\u305F',       id:'past',  meaning:'plain past',                minKnown:0,  minIntroduced:40 },
  { form:'\u3066',       id:'te',    meaning:'te-form (linking)',         minKnown:0,  minIntroduced:55 },
  { form:'\u3066\u3044\u308B', id:'teiru', meaning:'progressive',         minKnown:0,  minIntroduced:65 },
  { form:'\u305F\u3044', id:'tai',   meaning:'want to (desire)',          minKnown:0,  minIntroduced:70 },
  { form:'\u3051\u3069', id:'kedo',  meaning:'but / though',              minKnown:0,  minIntroduced:80 },
  { form:'\u305F\u3089', id:'tara',  meaning:'if / when (conditional)',   minKnown:0,  minIntroduced:95 },
]

// Grammar availability tracks INTRODUCED vocabulary, not the much smaller 'known'
// count. A learner with 100 introduced words was being given 6 particles and zero
// morphology — no を, no past tense, no ます, no ない — which makes ordinary Japanese
// impossible to build and sends every candidate to fallback.
function japaneseScaffoldFor(vocab) {
  const introduced = (vocab || []).filter(w => isLearnerTaught(w)).length
  const known = (vocab || []).filter(w => w.status === 'known').length
  // Either measure may unlock a block; introduced is the primary one.
  // When a block declares minIntroduced that value is AUTHORITATIVE. Treating it as
  // an alternative to minKnown meant `minKnown: 0` satisfied the OR for every
  // morphology block, unlocking たら and ている at ten words.
  return [...JAPANESE_GRAMMAR_SCAFFOLD, ...JAPANESE_MORPHOLOGY_SCAFFOLD]
    .filter(s => s.minIntroduced !== undefined
      ? introduced >= s.minIntroduced
      : known >= s.minKnown)
}

// §1 — "introduced" means actually encountered, NOT status !== 'new'. A word rated
// Hard stays status 'new' because it holds its slot, but the learner HAS seen it and
// it must remain usable as supporting vocabulary.
function isJapaneseIntroduced(w, activeTargetIds) {
  if (!w) return false
  if (activeTargetIds && activeTargetIds.has(w.id)) return true
  return isLearnerTaught(w)                       // v665: the ONE definition of taught
}

// §2 — the closed content set for one track.
function japaneseAllowedContent(vocab, targets) {
  const ids = new Set((targets || []).map(t => t.id))
  const prior = (vocab || []).filter(w => !ids.has(w.id) && isJapaneseIntroduced(w, ids))
  return { targets: targets || [], prior, all: [...(targets || []), ...prior] }
}

// Kana that is purely grammatical: inflection tails, particles, copula, fillers.
// These never count as content vocabulary.
const JA_GRAMMAR_KANA = new Set([
  '\u306F','\u304C','\u3092','\u306B','\u3067','\u3068','\u3082','\u306E','\u3078','\u304B','\u306D','\u3088','\u306A','\u3055','\u308F',
  '\u3060','\u3067\u3059','\u307E\u3059','\u3060\u3088','\u3060\u306D','\u3067\u3057\u305F','\u307E\u3057\u305F','\u3060\u3063\u305F',
  '\u3058\u3083','\u3058\u3083\u306A\u3044','\u306A\u3044','\u306A\u304B\u3063\u305F','\u305F','\u3066','\u305F\u3044','\u3088\u3046','\u305D\u3046',
  '\u304B\u3089','\u307E\u3067','\u3051\u3069','\u304C','\u306E\u3067','\u3057','\u3082\u3046','\u307E\u3060',
  '\u3046\u3093','\u306F\u3044','\u3044\u3044\u3048','\u3048','\u3042','\u3093',
])

// §12/§13 — never split on whitespace. Strip everything that is legitimately
// allowed (targets in any inflected form, prior content, scaffold, grammar kana,
// punctuation) and report whatever lexical material is left over.
function japaneseUnknownContent(sentence, allowed, scaffold) {
  let s = (sentence || '')
  if (!s) return []
  // 1. remove punctuation and spacing
  s = s.replace(/[\s\u3000\u3001\u3002\uFF1F\uFF01\u30FB\u2026\uFF0C\uFF0E\u300C\u300D~\u301C\-]/g, '')
  // 2. remove every allowed content word, longest first, in ALL its inflected forms
  const forms = []
  for (const w of (allowed || [])) {
    const lemma = w.lemma || w.japanese
    if (!lemma) continue
    forms.push(lemma)
    if (Array.isArray(w.permittedForms)) forms.push(...w.permittedForms)
    if (w.conjugationClass) forms.push(...japaneseConjugate(lemma, w.conjugationClass))
    // a kanji stem lets 高かった / 行った resolve even if a form is missing
    const stem = japaneseStemOf(w)
    if (stem && /[\u4E00-\u9FFF]/.test(stem)) forms.push(stem)
    // v651 §14 — the KANA spelling of a taught word is the same word (すき = 好き, ごはん = ご飯,
    // いっしょ = 一緒), not an untaught one
    jaKanaSpellingsOf(w).forEach(k => forms.push(k))
  }
  // 3. plus scaffold and grammatical kana
  for (const g of (scaffold || [])) forms.push(g.form)
  // Only MULTI-character grammar strings are removed here. Stripping single kana as
  // substrings erodes real words (\u3042 out of \u3084\u3042, \u3082 out of \u3082\u3046) and hides them; single
  // kana are handled by the whole-run test below instead.
  JA_GRAMMAR_KANA.forEach(k => { if (k.length > 1) forms.push(k) })
  forms.sort((a, b) => b.length - a.length)
  for (const f of forms) { if (f) s = s.split(f).join('') }
  // 4. Kanji or katakana left over is always untaught content.
  const leftovers = s.match(/[\u4E00-\u9FFF]+|[\u30A0-\u30FF\u30FC]+/g) || []
  // Leftover HIRAGANA also matters \u2014 \u3084\u3042 / \u3082\u3046 / \u3061\u3087\u3063\u3068 are real words a beginner has not
  // been taught. A run is only acceptable if it is ENTIRELY grammatical: stripping
  // single particles from inside a run would erode \u3082\u3046 to \u3046 and hide it.
  const kanaRuns = (s.match(/[\u3041-\u309F]+/g) || []).filter(r => {
    if (r.length < 2) return false                       // stray inflection residue
    if (JA_GRAMMAR_KANA.has(r)) return false             // a known grammatical string
    for (const ch of r) if (!JA_GRAMMAR_KANA.has(ch)) return true   // any non-grammar kana -> content
    return false                                          // wholly particles/copula
  })
  return [...new Set([...leftovers, ...kanaRuns])]
}

// v651 §14 — kana spellings and potential forms of TAUGHT words resolve to those words. This is
// lexical identity, not a whitelist: 行ける (can go) is 行く, すき is 好き; 飲み物 / コーヒー stay untaught.
function jaKanaSpellingsOf(w) {
  const out = []
  String((w && w.reading) || '').split(/\s*[\/\uFF0F|]\s*/).forEach(r => {
    const k = r.trim()
    if (k && k.length >= 2 && /^[\u3041-\u309F\u30FC]+$/.test(k) && k !== (w.japanese || '')) {
      out.push(k)
      // kana verb / i-adjective stems conjugate like the kanji form (くる → こない is irregular; skipped)
      if (/[\u308B\u3046\u304F\u3050\u3059\u3064\u306C\u3076\u3080]$/.test(k) && k.length >= 3 && k !== '\u304F\u308B') out.push(k.slice(0, -1))
    }
  })
  return out
}
const JA_POTENTIAL_BASE = { '\u3051':'\u304F', '\u3052':'\u3050', '\u305B':'\u3059', '\u3066':'\u3064', '\u306D':'\u306C', '\u3079':'\u3076', '\u3081':'\u3080', '\u3048':'\u3046', '\u308C':'\u308B' }
// 行ける → 行く · 使える → 使う · 飲める → 飲む · 帰れる → 帰る · 食べられる → 食べる
function jaLemmaCandidates(lemma) {
  const l = String(lemma || ''), out = [l]
  const m = /^(.+)([\u3051\u3052\u305B\u3066\u306D\u3079\u3081\u3048\u308C])\u308B$/.exec(l)
  if (m) out.push(m[1] + JA_POTENTIAL_BASE[m[2]])
  const r = /^(.+)\u3089\u308C\u308B$/.exec(l)
  if (r) out.push(r[1] + '\u308B')
  return out
}
function jaTaughtLexemeFor(token, inv) {
  const all = (inv && inv.allContent) || []
  for (const cand of jaLemmaCandidates(token)) {
    const hit = all.find(w => w.lemma === cand || w.japanese === cand || jaKanaSpellingsOf(w).includes(cand))
    if (hit) return hit
  }
  return null
}
// §5/§7C — Conversation Basics. A third category, distinct from SRS vocabulary and
// from grammar particles: the minimum framing needed for a conversation to exist at
// all. Never rated, never Known, never a slot. Deliberately tiny.
// ══ JAPANESE LEARNING INVENTORY — Building Blocks & Conversation Basics (Phase 2) ══
// Three separate streams: content vocabulary (belt totals), Conversation Basics (fixed
// chunks) and Building Blocks (grammatical CONCEPTS). A Building Block is a concept with
// register realisations — 食べています / 食べてます / 食べてる are ONE mastery item, not three.
// Static curriculum here; learner progress lives in its own store (JA_GRAMMAR_KEY) so
// vocabulary belt totals and word scheduling can never be affected.
