// Conversation Basics: fixed/semi-fixed chunks with their own mastery (never belt slots).
const JA_CONVERSATION_BASICS = [
  { id:'konnichiwa', form:'こんにちは', romaji:'konnichiwa', english:'hello', order:10, minKnown:0 },
  { id:'un', form:'うん', romaji:'un', english:'yeah', order:20, minKnown:0 },
  { id:'matane', form:'またね', romaji:'mata ne', english:'see you', order:30, minKnown:0 },
  { id:'jaa', form:'じゃあ', romaji:'jaa', english:'well then', order:40, minKnown:0 },
  { id:'soudane', form:'そうだね', romaji:'sou da ne', english:"yeah / that's true", order:50, minKnown:20 },
  { id:'iine', form:'いいね', romaji:'ii ne', english:'sounds good', order:60, minKnown:25 },
  { id:'honto', form:'ほんと？', romaji:'honto?', english:'really?', order:70, minKnown:30 },
  { id:'sokka', form:'そっか', romaji:'sokka', english:'I see', order:80, minKnown:35 },
  { id:'naruhodo', form:'なるほど', romaji:'naruhodo', english:'I see / makes sense', order:90, minKnown:45 },
  { id:'doushiyou', form:'どうしよう', romaji:'dou shiyou', english:'what should I do?', order:100, minKnown:60 },
]
const jaBlockById = id => JA_BUILDING_BLOCKS.find(b => b.id === id) || null
const jaBasicById = id => JA_CONVERSATION_BASICS.find(b => b.id === id) || null
// Surface form for the learner's current register — realisation only, never mastery.
function jaBlockRealisation(block, register) {
  if (!block) return ''
  const r = block.realisations
  if (!r) return block.label
  const reg = register === 'polite' ? 'polite' : register === 'polite-casual' ? 'politeCasual' : 'natural'
  return r[reg] || r.natural || block.label
}

// ── learner progress store (separate from tt-ja-vocab: belt totals cannot be affected) ──
// Records are SRS-shaped so the existing applyRating/calcInterval engine is reused as-is.
function jaProgressKeyOf(type, id) { return type + ':' + id }
function jaNewProgressRecord(type, id) {
  return { key: jaProgressKeyOf(type, id), type, itemId: id, status: 'new', interval: 0, dueDate: null,
           lastSeen: null, introducedAt: null, okStreak: 0, lapses: 0, exposures: 0, productiveExposures: 0 }
}
async function jaGrammarLoad() { try { return (await stGet(JA_GRAMMAR_KEY)) || {} } catch (e) { return {} } }
async function jaGrammarSave(store) { await stSet(JA_GRAMMAR_KEY, store); return store }
function jaGrammarGet(store, type, id) { return (store || {})[jaProgressKeyOf(type, id)] || jaNewProgressRecord(type, id) }
// Introduction is an explicit event: nothing is "due" before the learner has met it.
function jaGrammarIntroduce(store, type, id, when) {
  const k = jaProgressKeyOf(type, id)
  const rec = store[k] || jaNewProgressRecord(type, id)
  if (!rec.introducedAt) { rec.introducedAt = when || new Date().toISOString().slice(0, 10); rec.status = 'learning' }
  store[k] = rec; return rec
}
function jaGrammarRecordExposure(store, type, id, productive) {
  const k = jaProgressKeyOf(type, id)
  const rec = store[k] || jaNewProgressRecord(type, id)
  rec.exposures = (rec.exposures || 0) + 1
  if (productive) rec.productiveExposures = (rec.productiveExposures || 0) + 1
  rec.lastSeen = new Date().toISOString().slice(0, 10)
  store[k] = rec; return rec
}
// Same Hard/OK/Easy meaning and the same scheduling engine as vocabulary — separate data.
function jaGrammarApplyRating(store, type, id, rating) {
  const k = jaProgressKeyOf(type, id)
  const rec = store[k] || jaNewProgressRecord(type, id)
  const rated = applyRating({ ...rec, thai: rec.key }, rating)     // engine is record-shaped and language-neutral
  const out = { ...rec, status: rated.status, interval: rated.interval, dueDate: rated.dueDate,
                lastSeen: rated.lastSeen, okStreak: rated.okStreak, lapses: rated.lapses,
                introducedAt: rec.introducedAt || rated.introducedAt || new Date().toISOString().slice(0, 10) }
  store[k] = out; return out
}
function jaGrammarDue(store, type, today) {
  const t = today || new Date().toISOString().slice(0, 10)
  return Object.values(store || {}).filter(r => r && r.type === type && r.introducedAt && r.dueDate && r.dueDate <= t)
}
// Curriculum unlock: available when its word gate is met AND every prerequisite is introduced.
function jaBlocksAvailable(vocab, store) {
  const known = (vocab || []).filter(w => w.status === 'known' || w.status === 'learning').length
  return JA_BUILDING_BLOCKS.filter(b => known >= (b.minKnown || 0) &&
    (b.prereq || []).every(p => (jaGrammarGet(store, 'buildingBlock', p).introducedAt)))
}
function jaBasicsAvailable(vocab) {
  const known = (vocab || []).filter(w => w.status === 'known' || w.status === 'learning').length
  return JA_CONVERSATION_BASICS.filter(b => known >= (b.minKnown || 0))
}
// One-time, idempotent, additive: seeds progress records for anything the learner has
// already been exposed to through the legacy scaffolds. No learner data is overwritten.
async function jaGrammarMigrateV1(vocab) {
  const mig = (await stGet('tt-migrations')) || {}
  const store = await jaGrammarLoad()
  if (mig[JA_GRAMMAR_MIGRATION] && mig[JA_GRAMMAR_MIGRATION].status === 'done') return { store, changes: 0, already: true }
  const known = (vocab || []).filter(w => w.status === 'known' || w.status === 'learning').length
  let changes = 0
  const legacy = (typeof JAPANESE_GRAMMAR_SCAFFOLD !== 'undefined' ? JAPANESE_GRAMMAR_SCAFFOLD : [])
    .concat(typeof JAPANESE_MORPHOLOGY_SCAFFOLD !== 'undefined' ? JAPANESE_MORPHOLOGY_SCAFFOLD : [])
  legacy.forEach(g => {
    if (!jaBlockById(g.id)) return                                  // unknown legacy id: leave it alone
    const gate = Math.max(g.minKnown || 0, g.minIntroduced || 0)
    if (known >= gate) { const k = jaProgressKeyOf('buildingBlock', g.id); if (!store[k] || !store[k].introducedAt) { jaGrammarIntroduce(store, 'buildingBlock', g.id); changes++ } }
  })
  ;(typeof JAPANESE_CONVERSATION_BASICS !== 'undefined' ? JAPANESE_CONVERSATION_BASICS : []).forEach(b => {
    if (!jaBasicById(b.id)) return
    if (known >= (b.minKnown || 0)) { const k = jaProgressKeyOf('conversationBasic', b.id); if (!store[k] || !store[k].introducedAt) { jaGrammarIntroduce(store, 'conversationBasic', b.id); changes++ } }
  })
  await jaGrammarSave(store)
  mig[JA_GRAMMAR_MIGRATION] = { status: 'done', at: new Date().toISOString(), seeded: changes }
  await stSet('tt-migrations', mig)
  return { store, changes, already: false }
}

const JAPANESE_CONVERSATION_BASICS = [
  { id:'konnichiwa', form:'\u3053\u3093\u306B\u3061\u306F', romaji:'konnichiwa', english:'hello',          minKnown:0 },
  { id:'un',         form:'\u3046\u3093',                   romaji:'un',         english:'yeah',           minKnown:0 },
  { id:'matane',     form:'\u307E\u305F\u306D',             romaji:'mata ne',    english:'see you',        minKnown:0 },
  { id:'jaa',        form:'\u3058\u3083\u3042',             romaji:'jaa',        english:'well then',      minKnown:0 },
  // v651 §14 — ねえ ("hey" / "say…") is the attention-getting form of the sentence particle ね: a
  // conversation building block, not content vocabulary. Unlocked with the second tier of basics.
  { id:'nee',        form:'\u306D\u3048',                   romaji:'nee',        english:'hey (getting attention)', minKnown:20 },
]
function japaneseBasicsFor(vocab) {
  const known = (vocab || []).filter(w => w.status === 'known').length
  return JAPANESE_CONVERSATION_BASICS.filter(b => known >= b.minKnown)
}

// §19 — one explicit inventory object. Every generation stage reads from this;
// no stage is allowed to bypass it.
function japaneseLearnerInventory(vocab, targets) {
  const allow = japaneseAllowedContent(vocab, targets)
  const grammarScaffold = japaneseScaffoldFor(vocab)
  const conversationBasics = japaneseBasicsFor(vocab)
  const introducedCount = allow.all.length
  return {
    currentTargets: allow.targets,
    introducedVocabulary: allow.prior,
    allContent: allow.all,
    conversationBasics,
    grammarScaffold,
    // §20 — zero-beginner mode
    isZeroBeginner: (vocab || []).filter(w => w.status === 'known').length === 0 && introducedCount <= 3,
  }
}

// Everything the learner may legitimately see, as raw surface strings.
function japaneseInventoryForms(inv) {
  return [
    ...inv.conversationBasics.map(b => b.form),
    ...inv.grammarScaffold.map(g => g.form),
  ]
}

// §18/§23 — producibility. Runs on EVERY learner-facing Japanese line, framing
// included, not just the recall sentences.
function japaneseCheckLine(jp, inv) {
  const extra = inv.conversationBasics.map(b => ({ japanese: b.form, lemma: b.form }))
  const raw = japaneseUnknownContent(jp, [...inv.allContent, ...extra], inv.grammarScaffold)
  // Determiners, case/sentence particles, discourse markers and common adverbs are
  // STRUCTURE, not content vocabulary. この and その were being reported as
  // "untaught content", which is what rejected 古い recall 3 and several others.
  const unknown = raw.filter(w => {
    const c = jaTokenClass(w)
    return !(c === 'determiner' || c === 'case-particle' || c === 'sentence-particle' ||
             c === 'discourse' || c === 'nominaliser' || c === 'punctuation' ||
             c === 'adverb' || c === 'interrogative')
  })
  return { ok: unknown.length === 0, unknown }
}

// ── Vocabulary scarcity ──────────────────────────────────────────────────────
// §1 — diversity pressure must scale with how much language the learner actually
// has. Demanding three distinct grammar patterns and global novelty from a six-word
// inventory is what produced 1/3 and 0/3 recalls: the search space was empty.
function japaneseScarcityLevel(inv) {
  const n = ((inv && inv.allContent) || []).length
  if (n <= 15) return 'A'
  if (n <= 50) return 'B'
  return 'C'
}
const SCARCITY_RULES = {
  A: { requirePatternVariety:false, requireScenarioVariety:false, allowCrossTargetReuse:true,  allowNearDuplicate:true,  maxTiers:4 },
  B: { requirePatternVariety:false, requireScenarioVariety:true,  allowCrossTargetReuse:false, allowNearDuplicate:true,  maxTiers:6 },
  C: { requirePatternVariety:true,  requireScenarioVariety:true,  allowCrossTargetReuse:false, allowNearDuplicate:false, maxTiers:11 },
}
function scarcityRules(inv) { return SCARCITY_RULES[japaneseScarcityLevel(inv)] }

// §10/§11 — complexity from CONTENT segments, not character runs. A long kana run
// is not automatically many units; 今日何する？ is three content items, not six.
// v665: japaneseComplexity removed — an unreferenced second Japanese length counter (complexityUnits is the one)

// §12/§13 — lexical identity comes from the model's own segments, never from
// slicing kanji/kana. This is what produced nonsense reports like 決 / まった.
function japaneseUnknownFromSegments(pair, inv) {
  const segs = Array.isArray(pair && pair.segments) ? pair.segments : []
  if (!segs.length) return null            // caller falls back to surface scanning
  const unknown = []
  for (const s of segs) {
    const surface = (s && s.surface) || ''
    if (!surface || !/[\u3040-\u30FF\u4E00-\u9FFF]/.test(surface)) continue
    if (s.type === 'grammar' || s.type === 'punct') continue
    const lemma = s.lemma || surface
    // resolve against current targets + introduced vocabulary + scaffold + basics
    const hit = (inv.allContent || []).some(w => w.lemma === lemma || w.japanese === lemma || w.japanese === surface)
      || !!jaTaughtLexemeFor(lemma, inv) || !!jaTaughtLexemeFor(surface, inv)          // v651 §14 kana / potential forms
      || (inv.grammarScaffold || []).some(g => g.form === surface)
      || (inv.conversationBasics || []).some(b => b.form === surface || b.form === lemma)
    if (!hit) {
      // §13 — report the LEMMA, so the message is actionable
      if (!unknown.includes(lemma)) unknown.push(lemma)
    }
  }
  return unknown
}

// §4 — three dedupe levels instead of one global rejection.
//   A. same target + same Japanese          -> always reject
//   B. same Japanese, different target      -> allowed at scarcity A (§3)
//   C. near-duplicate shape                 -> allowed at scarcity A, tightened later
function japaneseDuplicateVerdict(jp, targetId, seenMap, rules) {
  const key = jaDedupeKey(jp)
  const prev = seenMap.get(key)
  if (!prev) return { ok: true }
  if (prev.targetId === targetId) return { ok: false, level: 'A', reason: 'identical sentence already used for this target' }
  if (rules.allowCrossTargetReuse) return { ok: true, note: 'reused across targets (allowed at low inventory)' }
  return { ok: false, level: 'B', reason: 'sentence already used for another target' }
}

// §11 — the enforcement point.
function validateJapaneseContentVocabulary(sentence, allowed, scaffold) {
  const unknown = japaneseUnknownContent(sentence, allowed, scaffold)
  if (!unknown.length) return { ok: true, unknown: [] }
  return { ok: false, unknown }
}

// §2/§11 — grammatical glue. Available to the generator from lesson one, but never
// SRS targets: they take no slot, earn no Known status and do not affect belt rank.
const JAPANESE_FUNCTION_WORDS = [
  { w:'は',  r:'wa',    e:'(topic marker)' },
  { w:'が',  r:'ga',    e:'(subject marker)' },
  { w:'を',  r:'wo',    e:'(object marker)' },
  { w:'に',  r:'ni',    e:'(to / at)' },
  { w:'で',  r:'de',    e:'(at / by means of)' },
  { w:'と',  r:'to',    e:'(and / with)' },
  { w:'も',  r:'mo',    e:'(also)' },
  { w:'の',  r:'no',    e:'(possessive / of)' },
  { w:'へ',  r:'e',     e:'(towards)' },
  { w:'から',r:'kara',  e:'(from / because)' },
  { w:'まで',r:'made',  e:'(until)' },
  { w:'ね',  r:'ne',    e:'(right? / soft agreement)' },
  { w:'よ',  r:'yo',    e:'(emphasis)' },
  { w:'か',  r:'ka',    e:'(question marker)' },
]
const JAPANESE_GRAMMAR_NOTE =
  'GRAMMAR SUPPORT (always available, never counted as new vocabulary):\n' +
  'Particles: ' + JAPANESE_FUNCTION_WORDS.map(f => f.w).join(' ') + '\n' +
  'Inflection: negative, past, て-form, question formation, and the copula as the register requires.\n' +
  'Use these freely to make the target words usable \u2014 they are not new content words.'

// §17 — Japanese inflects, so exact-substring matching is wrong. This is the seam where
// real morphology goes once the bank carries lemma/conjugationClass metadata.
function japaneseStemOf(target) {
  const lemma = (target && (target.lemma || target.japanese)) || ''
  if (!lemma) return ''
  // Order matters: \u52C9\u5F37\u3059\u308B also ends in \u308B, so suru-verbs must be tested first.
  if (/\u3059\u308B$/.test(lemma) && lemma.length > 2) return lemma.slice(0, -2)   // suru-verb
  if (/\u308B$/.test(lemma) && lemma.length > 1)      return lemma.slice(0, -1)   // ichidan / -ru
  if (/\u3044$/.test(lemma) && lemma.length > 1)      return lemma.slice(0, -1)   // i-adjective
  // Godan verbs conjugate on the final mora (\u884C\u304F \u2192 \u884C\u3063\u305F/\u884C\u304B\u306A\u3044); the stem is what precedes it.
  if (/[\u304F\u3050\u3059\u3064\u306C\u3076\u3080\u3046]$/.test(lemma) && lemma.length > 1) return lemma.slice(0, -1)
  return lemma
}
function matchesJapaneseTarget(sentence, target) {
  const s = (sentence || '')
  if (!s || !target) return false
  const lemma = target.lemma || target.japanese || ''
  if (!lemma) return false
  if (s.includes(lemma)) return true                       // exact dictionary form
  // v651 §13F — the kana spelling of a noun / adjective target (すき for 好き, ごはん for ご飯). Verbs are
  // excluded: いく would match inside いくら; their inflection is handled by the form list / stem below.
  if (/[\u4E00-\u9FFF]/.test(lemma) && !/verb/.test(String(target.partOfSpeech || '')) && jaKanaSpellingsOf(target).some(k => k.length >= 2 && s.includes(k))) return true

  // Explicit forms win: either supplied by the bank or generated from the
  // conjugation class. This is precise, so it cannot produce false positives.
  const listed = Array.isArray(target.permittedForms) ? target.permittedForms : null
  if (listed && listed.some(f => f && s.includes(f))) return true
  if (target.conjugationClass) {
    const forms = japaneseConjugate(lemma, target.conjugationClass)
    if (forms.some(f => f && f.length > 1 && s.includes(f))) return true
    // A known conjugation class means the form list is authoritative; do not fall
    // through to loose stem matching, which is what lets unrelated words slip in.
    return false
  }

  // No morphology metadata: fall back to a stem, guarded so short kana cannot match
  // spuriously. A single kanji is discriminating; a single kana is not.
  const stem = japaneseStemOf(target)
  if (stem) {
    const kanjiStem = /[\u4E00-\u9FFF]/.test(stem)
    const longEnough = kanjiStem ? stem.length >= 1 : stem.length >= 2
    if (longEnough && s.includes(stem)) return true
  }
  return false
}

// §9/§18 — complexity cannot be measured by spaces. Count Japanese content units instead:
// kanji runs, kana runs and particles each count as roughly one "unit".
// v665: japaneseUnitCount removed — an unreferenced second Japanese length counter (complexityUnits is the one)

// §7/§8 — same progression and same slot table as Thai, driven by the Japanese Known count.
function japaneseBeltFor(vocab) { return calculateBeltRank((vocab||[]).filter(w => w.status === 'known').length) }
// Per-TRACK allowance for the learner's active rank. Starting a second track the
// same day grants the full allowance again — the limit is per track, not per day.
function beltNewAllowanceFor(vocab) {
  return getNewWordLimitForBelt(earliestIncompleteBelt(vocab) || 'White')
}
// Per-track, rank-configured. Previously newSlotsFor(vocab), which keys on total
// known count and so drifted away from the learner's actual belt.
// v654 §12 — Japanese Daily introduces exactly JA_DAILY_NEW_WORDS (3); the belt allowance is Thai's
function japaneseSlotsFor(vocab) { return newWordsPerTrack('ja', 'daily', vocab) }
// v665: the Japanese length numbers come from the ONE belt contract (no known-count table)
function japaneseUnitRange(vocab) {
  const cc = getLearnerComplexityContract({ lang: 'ja', vocab })
  return { min: cc.preferredMin, max: cc.preferredMax, hardMax: cc.hardMax, contract: cc }
}



// ── Japanese generation & validation ─────────────────────────────────────────
// Mirrors the depth of the Thai guardrails (§15). Where a Thai rule is language-
// independent it is preserved verbatim in intent; where it was Thai-specific
// (phonetic alignment, ครับ/ค่ะ particles) the Japanese equivalent protects the
// same class of failure (§29): segment/reading/romaji alignment and register.

function japaneseRegisterContract(registerId) {
  const r = JAPANESE_REGISTER_RULES[registerId] || JAPANESE_REGISTER_RULES[JA_REGISTER_DEFAULT]
  return r.contract
}

// v665: buildJapaneseTrackPrompt removed — unreferenced dead copy that carried its own length ladder (one source of truth: BELT_COMPLEXITY)

function buildJapaneseConvoPrompt(targets, vocab, registerId) {
  const range = japaneseUnitRange(vocab)
  const words = (targets||[]).slice(0, 15).map(t => t.japanese + '=' + t.english).join(', ')
  const reg = JAPANESE_REGISTER_RULES[registerId] || JAPANESE_REGISTER_RULES[JA_REGISTER_DEFAULT]
  const GREET = {
    polite:  '\u3053\u3093\u306B\u3061\u306F\u3002 / \u304A\u4E45\u3057\u3076\u308A\u3067\u3059\u3002 / \u4ECA\u65E5\u306F\u3069\u3046\u3067\u3059\u304B\uFF1F',
    natural: '\u4E45\u3057\u3076\u308A\u3002 / \u5143\u6C17\u3060\u3063\u305F\uFF1F / \u3082\u3046\u6765\u3066\u305F\u3093\u3060\u3002 / \u4ECA\u65E5\u3069\u3046\uFF1F',
    casual:  '\u4E45\u3057\u3076\u308A\uFF01 / \u5143\u6C17\uFF1F / \u3084\u3063\u3068\u6765\u305F\uFF01 / \u4F55\u3057\u3066\u305F\u306E\uFF1F',
  }
  const PART = {
    polite:  '\u307E\u305F\u4F1A\u3044\u307E\u3057\u3087\u3046\u3002 / \u6C17\u3092\u3064\u3051\u3066\u5E30\u3063\u3066\u304F\u3060\u3055\u3044\u3002 / \u307E\u305F\u4ECA\u5EA6\u3002',
    natural: '\u307E\u305F\u306D\u3002 / \u3058\u3083\u3042\u3001\u307E\u305F\u3002 / \u6C17\u3092\u3064\u3051\u3066\u306D\u3002 / \u307E\u305F\u4ECA\u5EA6\u884C\u3053\u3046\u3002',
    casual:  '\u3058\u3083\u3001\u307E\u305F\uFF01 / \u307E\u305F\u306A\u3002 / \u6C17\u3092\u3064\u3051\u3066\uFF01',
  }
  const inv = japaneseLearnerInventory(vocab, targets)
  const system =
    'You are a Japanese language teacher writing realistic spoken Japanese conversations for learners. ' +
    'Write natural Japanese as a Japanese adult would actually speak in the selected register \u2014 not translated English.\n\n' +
    (inv.isZeroBeginner
      ? '=== ZERO BEGINNER ===\nThis learner knows essentially NO Japanese. Every Japanese line must be extremely short ' +
        'and use ONLY the words listed below. Fragments are correct. No contractions (\u3066\u305F/\u3093\u3060/\u3068\u3044\u305F/\u3066\u308B). ' +
        'No multi-clause sentences.\n\n'
      : '') +
    japaneseRegisterContract(registerId)
  const user =
    '=== THE ONLY JAPANESE YOU MAY USE ===\n' +
    'CONTENT WORDS:\n' + inv.allContent.map(w => '  ' + w.japanese + ' [' + w.reading + '] ' + w.romaji + ' = ' + w.english +
      (w.note ? '  \u2014 use when ' + w.note : '')).join('\n') + '\n' +
    'CONVERSATION BASICS:\n' + (inv.conversationBasics.length ? inv.conversationBasics.map(b => '  ' + b.form + ' [' + b.romaji + '] = ' + b.english).join('\n') : '  (none)') + '\n' +
    'GRAMMAR:\n' + inv.grammarScaffold.map(g => '  ' + g.form + ' [' + g.romaji + '] \u2014 ' + g.meaning).join('\n') + '\n' +
    'Any other Japanese word is FORBIDDEN in the Japanese lines. \u00A712/\u00A715: character names appear as ' +
    'speaker labels only \u2014 NEVER inside the Japanese sentences (no \u30E6\u30DF, no \u30B1\u30F3\u30B8).\n' +
    (scarcityRules(inv).allowNearDuplicate
      ? 'The learner has very little Japanese. Keep every Japanese line extremely short and build it from the ' +
        'Conversation Basics above plus the content list. Simple framing is correct \u2014 do not invent native dialogue.\n'
      : '') +
    'The ENGLISH scene description may be rich and specific; the JAPANESE must stay within this list.\n\n' +
    'Write a short coherent scene between two adult friends, A (male) and B (female), with a real ' +
    'conversational goal and actual progression \u2014 not disconnected lines. Do NOT force every word in.\n' +
    range.contract.promptRule + '\n\n' +
    'The lesson is framed by a greeting exchange and a parting exchange.\n' +
    'GREETING must suit the scene, the relationship and the register. Vary it \u2014 do not reuse one stock phrase.\n' +
    '  ' + reg.label + ' greetings of this TYPE: ' + (GREET[reg.id] || GREET.natural) + '\n' +
    'PARTING must end the conversation naturally, again matching the register.\n' +
    '  ' + reg.label + ' partings of this TYPE: ' + (PART[reg.id] || PART.natural) + '\n' +
    'B\u2019s reply must NOT simply repeat A\u2019s wording \u2014 it should read as a real exchange.\n' +
    'Every line needs japanese, reading (kana), romaji (Hepburn, spaced by word) and english. ' +
    'Romaji must match the form actually written, never the dictionary form.\n' +
    'Each *_prompt is a plain English instruction of what to say \u2014 no Japanese, no romaji in it.\n' +
    'Return ONLY JSON:\n' +
    '{"scene":"2-sentence scene in English","characterA":"name and role","characterB":"name and role",' +
    '"opening":"...","opening_reading":"...","opening_romaji":"...","opening_english":"...","opening_prompt":"...",' +
    '"reply":"...","reply_reading":"...","reply_romaji":"...","reply_english":"...","reply_prompt":"...",' +
    '"closing":"...","closing_reading":"...","closing_romaji":"...","closing_english":"...","closing_prompt":"...",' +
    '"closing_reply":"...","closing_reply_reading":"...","closing_reply_romaji":"...","closing_reply_english":"...","closing_reply_prompt":"..."}'
  return { system, user }
}

// §22 — Japanese validator. Same "never silently accept" philosophy as Thai.
// v665: validateJapanesePairs removed — unreferenced dead copy that carried its own length ladder (one source of truth: BELT_COMPLEXITY)

// §23 — targeted repair instructions, same retry philosophy as Thai.
function japaneseRepairInstruction(failures) {
  if (!failures || !failures.length) return ''
  const uniq = [...new Set(failures)].slice(0, 6)
  return 'The previous attempt failed these checks. Fix ONLY these and regenerate:\n- ' + uniq.join('\n- ')
}

// ── Word utility scoring ─────────────────────────────────────────────────────
// Ranks vocabulary by usefulness for everyday spoken Thai so that brand-new words
// are introduced most-useful-first. Grammar/function words and question patterns
// score highest; regional, ceremonial and exotic-produce terms score lowest.
const UTIL_CORE = {
  '\u0e2d\u0e22\u0e39\u0e48':100,'\u0e15\u0e49\u0e2d\u0e07':100,'\u0e22\u0e31\u0e07\u0e44\u0e21\u0e48':98,'\u0e1a\u0e32\u0e07':92,'\u0e02\u0e35\u0e49':70,
  '...\u0e2d\u0e22\u0e39\u0e48\u0e17\u0e35\u0e48\u0e44\u0e2b\u0e19':97,'...\u0e43\u0e2b\u0e49\u0e2b\u0e19\u0e48\u0e2d\u0e22':96,'...\u0e40\u0e1b\u0e47\u0e19\u0e2d\u0e22\u0e48\u0e32\u0e07\u0e44\u0e23':94,'\u0e15\u0e31\u0e49\u0e07\u0e41\u0e15\u0e48...\u0e16\u0e36\u0e07...':88,
  '\u0e40\u0e22\u0e47\u0e19':86,'\u0e2a\u0e14':82,'\u0e0a\u0e32':80,'\u0e0a\u0e48\u0e27\u0e07':78,'\u0e44\u0e1b\u0e14\u0e49\u0e27\u0e22\u0e01\u0e31\u0e19':78,'\u0e17\u0e32\u0e07\u0e2d\u0e2d\u0e01':76,
  '\u0e40\u0e02\u0e49\u0e32\u0e40\u0e21\u0e37\u0e2d\u0e07':74,'\u0e19\u0e49\u0e33\u0e21\u0e31\u0e19':73,'\u0e19\u0e4d\u0e49\u0e32\u0e21\u0e31\u0e19':73,'\u0e43\u0e1a\u0e40\u0e2a\u0e23\u0e47\u0e08':72,'\u0e2b\u0e19\u0e36\u0e48\u0e07\u0e43\u0e1a':70,
  '\u0e2b\u0e21\u0e39\u0e48\u0e1a\u0e49\u0e32\u0e19':68,'\u0e01\u0e34\u0e08\u0e01\u0e23\u0e23\u0e21':66,
  '\u0e21\u0e30\u0e19\u0e32\u0e27':60,'\u0e21\u0e30\u0e1e\u0e23\u0e49\u0e32\u0e27':58,'\u0e1c\u0e31\u0e14\u0e01\u0e30\u0e40\u0e1e\u0e23\u0e32':56,'\u0e1b\u0e23\u0e30\u0e40\u0e1e\u0e13\u0e35':50,'\u0e40\u0e14\u0e34\u0e19\u0e1b\u0e48\u0e32':48,'\u0e1b\u0e34\u0e14\u0e40\u0e17\u0e2d\u0e21':46,
  '\u0e2a\u0e31\u0e1b\u0e1b\u0e30\u0e23\u0e14':40,'\u0e25\u0e33\u0e44\u0e22':34,'\u0e0a\u0e32\u0e27\u0e44\u0e17\u0e22\u0e43\u0e2b\u0e0d\u0e48':20,'\u0e01\u0e32\u0e23\u0e1a\u0e27\u0e0a\u0e40\u0e13\u0e23':18,
}
const UTIL_HINTS = [
  [/\b(hello|goodbye|good night|good morning|good afternoon|good evening|see you|take care|thank|sorry|excuse me|welcome|how are|nice to (see|meet)|long time no see|good luck|safe trip|have a (nice|good|great))\b/i, 95],
  [/^(to be|to be located|to be able|must|have to|not yet|some, any|to want|to have|to go|to come|to give|to get|to do|to make|to say|to know|please)[.,]?$/i, 90],
  [/\b(where|what|how many|how much|when|why|who|which)\b/i, 88],
  [/\.\.\./, 85],
  [/\b(go|come|eat|drink|do|make|give|take|get|say|know|see|buy|pay|help)\b/i, 78],
  [/\b(today|tomorrow|now|time|hour|day|week|month|year|morning|night)\b/i, 74],
  [/\b(money|price|shop|market|food|water|rice|house|home|room|road|car|bus)\b/i, 70],
  [/\b(hot|cold|big|small|good|bad|near|far|fast|slow|cheap|expensive)\b/i, 68],
  [/\b(festival|ceremony|ordination|ritual|tradition|temple fair)\b/i, 22],
  [/\b(people|tribe|ethnic|province|district)\b/i, 25],
  [/\b(longan|rambutan|durian|lychee|tamarind|guava|papaya)\b/i, 32],
]
function wordUtility(w) {
  const t = (w.thai || '').trim()
  if (UTIL_CORE[t] != null) return UTIL_CORE[t]
  const e = (w.english || '').toLowerCase()
  for (const [re, score] of UTIL_HINTS) if (re.test(e)) return score
  const syl = t.replace(/[\u0e30-\u0e4e]/g, '').length
  return Math.max(30, 62 - syl * 2)
}
// A word is "never shown" only if it has no review history at all. Words imported
// as hard from lesson data have repCount > 0 — they were seen, just not learned.
function isUnseen(w) { return (w.repCount || 0) === 0 && !w.lastSeen }

// Brand-new words carried per track; a slot frees only on 'ok' or better.
// Scaled by belt: early belts are narrow (100 words) and every word is built from
// scratch, while later belts are 10x wider and new words are mostly recombinations
// of known morphemes. Deliberately below the usual 15-25/day Anki advice because a
// "word" here costs 3 productive-recall sentence pairs, not one recognition card.

// The belt page's "Introducing N new words per track" now comes from the SAME
// config the selector uses, so the two can never disagree again.
function newSlotsFor(vocab) {
  return getNewWordLimitForBelt(earliestIncompleteBelt(vocab) || 'White')
}
const OK_STREAK_TO_KNOWN = 7
const OK_STREAK_TO_KNOWN_LAPSED = 9

