    const unresolvedRecalls = (part.missingRecalls || []).map(m => ({ targetId: m.targetId, target: m.targetJapanese, recallIndex: m.recallIndex, state: RECALL_TERMINAL_STATE, lastFailure: m.lastFailure || null }))
