    if (s[i] === '\u0E46') { spans.push({ rawThai: s, matchedSpan: '\u0E46', matchedEntry: '\u0E46', matchLength: 1, allowed: true, repetitionMark: true, remainingText: s.slice(i + 1) }); i++; continue }
