        if (allowedNow.has(tok)) return
        if (thaiSupportBlockCategory(_toks, si)) return            // v654 §7: authorised support item in its support position
        // Compositional fallback: a blocked compound is fine when allowed units
        // cover it completely (โทรหา = โทร + หา).
        const _u = new Set(THAI_EXTRA_UNITS)
        vocab.forEach(w => { const t2 = w.thai || w.t; if (t2) _u.add(t2) })
        if (!resolveThaiSpan(tok, allowedNow, _u).covered) offenders.push(tok)
