  if (/adverb/.test(pos)) return 'ADVERB'
  if (/adjective|na-adjective|i-adjective/.test(pos)) return 'STATE/ADJECTIVE'
  if (/verb/.test(pos)) return 'VERB'
  if (/noun/.test(pos)) return 'NOUN'
