function targetRoleLine(role, t, lang) {
  return 'TARGET ROLE: ' + role + ' — ' + (TARGET_ROLE_GUIDE[role] || TARGET_ROLE_GUIDE.OTHER) + '. Do not paste its English gloss into a template.\n'
}

