const LISTENING_SLOT_EXPECTS = { AGE: 'an age', DURATION: 'a length of time', AMOUNT: 'an amount / price', TIME: 'a time', PLACE: 'a place', PERSON: 'a person', REASON: 'a reason (a short clause — never a bare yes / no or a bare adjective)', STATE: 'how it is', THING: 'the thing asked about', YESNO: 'yes / no (or a qualified answer)', PHONE: 'the phone number (a few digits)' }
