  const qt = LN_QTYPE_RX.find(x => x.q.test(a))
  if (!qt) return null
  if (LN_BARE_YESNO.test(b)) return qt.expects.toUpperCase().replace(/^AN? /, '') + ' question ("' + a.slice(0, 40) + '") expects ' + qt.expects + ', got a bare "' + b + '"'
