    const transitive = /\b(eat|drink|buy|take|use|see|look|watch|want|have|need|find|bring|give|pay|order|make|do|wait)\b/.test(g)
    const stative = /\b(know|understand|like|love|want|think|mean|remember|forget|believe|feel|hope|be|is|exist)\b/.test(g) && !motion
