    const slot = M.get(q.id).asks || _lnQuestionSlot(q)
    const filler = slot === 'REASON' ? null : (pick(m => m.valueType === slot && m.canAnswer.includes(slot)) || pick(m => m.canAnswer.includes(slot) && listeningSlotAccepts(slot, _lnFillerType(byId.get(m.id)))))
    const verb = /^(PLACE|THING|TIME|REASON|PERSON)$/.test(slot) ? pick(m => m.valueType === 'ACTION' && (m.collocations.includes(slot) || (slot !== 'PLACE' && slot !== 'TIME' && m.requiredComplements.length))) : null
    // a reply word answers a yes/no question
    const yn = !filler && slot === 'YESNO' ? pick(m => m.valueType === 'YESNO') : null
