  const rejected = []
  if (Array.isArray(glosses)) {
    const pool = glosses.concat(sc.requiredTargetIds.map(id => String((byId.get(id) || {}).gloss || '')))
    chosen = null
    for (const c of cands) { const f = sceneLanguageFeasibility(c, pool); if (f.feasible) { chosen = c; break } rejected.push({ text: c.text, missing: f.missing }) }
    chosen = chosen || cands[cands.length - 1]
  }
  sc.feasibility = { checked: Array.isArray(glosses), situation: chosen.text, needs: chosen.needs || [], rejected }
  // v669 §13 — WHO / WHERE / WHY / WHAT (objective) of the scene, planned before targets are realised as text
  const set0 = LISTENING_SCENE_SETTING[top[0]] || LISTENING_SCENE_SETTING._
  sc.intent = { who: friends ? 'two friends' : set0.who, where: set0.where, why: set0.why,
    what: top[0] ? (LISTENING_SCENE_OBJECTIVE[top[0]] || 'talk about ' + top[0]) : 'have a short everyday chat', situation: chosen.text.replace(/^They meet and say hello; then /, '') }
  let situation = chosen.text
